exports.id=689,exports.ids=[689],exports.modules={1094:()=>{},2056:(a,b,c)=>{"use strict";c.r(b),c.d(b,{default:()=>f,metadata:()=>e});var d=c(5735);c(2704);let e={title:"AOSDF — AI-Orchestrated Software Development",description:"The foundations of an AI-orchestrated software factory: specifications, coordinated agents, and evidence-based validation."};function f({children:a}){return(0,d.jsxs)("html",{lang:"en",children:[(0,d.jsxs)("head",{children:[(0,d.jsx)("link",{rel:"preconnect",href:"https://fonts.googleapis.com"}),(0,d.jsx)("link",{rel:"preconnect",href:"https://fonts.gstatic.com",crossOrigin:"anonymous"}),(0,d.jsx)("link",{href:"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap",rel:"stylesheet"})]}),(0,d.jsx)("body",{children:a})]})}},2516:(a,b,c)=>{"use strict";c.d(b,{e:()=>d});let d={id:"ai-engineer-fde",title:"AI Engineer / FDE",description:"An applied path from learning fundamentals through dependable AI systems and customer delivery. ML foundations, queues, and scale and system design are ready to read; the remaining modules show the intended sequence.",modules:[{id:"ml-foundations",title:"ML foundations",stage:"01 \xb7 Foundations",summary:"Frame a learning problem, prepare data, understand training, evaluate decisions, and plan inference.",status:"available",topics:[]},{id:"cloud-foundations",title:"AWS and cloud foundations",stage:"02 \xb7 Foundations",summary:"Choose cloud primitives, networking, compute, and delivery tools for a workload and its trust boundaries.",status:"planned",topics:["Regions, availability zones, edge locations, and multi-region placement","IAM, identity boundaries, and least-privilege access","VPCs, public and private subnets, routing, and network controls","DNS, TCP versus UDP, HTTP/2 and HTTP/3, and gRPC","EC2, Docker containers, Kubernetes, and managed container services","Lambda, cold starts, and serverless limits","S3, relational databases, NoSQL, and storage choices","Infrastructure as code with Terraform and Helm charts","CI/CD pipelines, build caching, dependency conflicts, and reproducible builds","Service choice, cloud monitoring, and cost trade-offs"]},{id:"async-systems",title:"Queues and reliable delivery",stage:"03 \xb7 Systems",summary:"Learn what queues do and when to use them, then make background work recoverable across failures.",status:"available",topics:["Producers, message queues, consumers, workers, and job scheduling with cron","Publish-subscribe and event-driven architecture","Throughput, queue depth, latency, and backpressure","Timeouts, retries, exponential backoff, jitter, and circuit breakers","Dead-letter queues, poison messages, and replay","Idempotency keys, duplicate effects, and delivery guarantees","Distributed transactions, the outbox pattern, and saga compensation","Webhooks, WebSockets, server-sent events, and long polling","Failure recovery, ordering, and operational visibility"]},{id:"models-transformers",title:"Neural networks and transformers",stage:"04 \xb7 AI foundations",summary:"Understand how modern models represent, train on, and generate sequences.",status:"planned",topics:["Neurons, layers, and backpropagation","Tokens and embeddings","Attention and transformer blocks","Pretraining, fine-tuning, and inference","Context limits and model tradeoffs"]},{id:"scale-design",title:"Scale and system design",stage:"05 \xb7 Systems",summary:"Design API, data, and compute paths for peak load, consistency needs, and failure modes.",status:"available",topics:["Requirements, capacity estimates, throughput, latency, and p99 tail latency","Horizontal versus vertical scaling, autoscaling, and load balancing","Reverse proxies, API gateways, service discovery, and rate limiting","CDN and edge caching, application caches, and cache invalidation","Database indexing, query optimization, and N+1 queries","Connection pooling, read replicas, and replication lag","Partitioning, sharding, and hot partitions","CAP trade-offs, network partitions, clock skew, and eventual consistency","Optimistic and pessimistic locking, distributed locks, and leader election","Race conditions, deadlocks, thread safety, memory leaks, and garbage collection","API and schema versioning, semantic versioning, and compatibility","Architecture review and explicit trade-off decisions"]},{id:"embeddings",title:"Embeddings and vector search",stage:"06 \xb7 AI systems",summary:"Represent content for similarity search and maintain a useful index.",status:"planned",topics:["Embedding spaces and similarity","Chunking and document metadata","Vector indexes and approximate search","Filtering and permission boundaries","Search quality and index freshness"]},{id:"rag",title:"Retrieval augmented generation",stage:"07 \xb7 AI systems",summary:"Build grounded answers from controlled, current sources.",status:"planned",topics:["Ingestion and source provenance","Retrieval and context assembly","Grounded generation and citations","No-evidence behavior","Access control across the pipeline"]},{id:"rag-evaluation",title:"Retrieval and answer evaluation",stage:"08 \xb7 AI systems",summary:"Measure what retrieval finds and what an answer claims.",status:"planned",topics:["Representative question sets","Recall and ranking measures","Answer faithfulness and citation checks","Hybrid retrieval and reranking","Failure diagnosis and regression gates"]},{id:"agents-workflows",title:"Agents and workflow execution",stage:"09 \xb7 AI systems",summary:"Let models propose steps while deterministic code controls authority and effects.",status:"planned",topics:["Tool schemas and validation","Workflow state and persistence","Authorization and approval gates","Retries, compensation, and recovery","Tracing agent decisions and outcomes"]},{id:"production-ai",title:"Production AI, cost, and security",stage:"10 \xb7 Production",summary:"Ship and operate AI features with measured quality, secure boundaries, recoverable releases, and clear budgets.",status:"planned",topics:["AI gateway, provider fallback, latency budgets, and token costs","Observability: monitoring, logging, distributed tracing, metrics, and alerts","SLIs, SLOs, error budgets, and alert response","Feature flags, blue-green deployments, canary releases, and rolling deployments","Health checks, liveness and readiness probes, and rollbacks","Threat modeling, prompt injection, and safe tool boundaries","Secrets management, IAM, and credential rotation","OAuth, JWT lifecycle and rotation, and session security","TLS, encryption in transit, and encryption at rest","CORS, CSRF, SQL injection, XSS, and SSRF defenses","WAF, DDoS protection, abuse controls, and tenant isolation","Backups, disaster recovery, failover, and multi-region recovery","Chaos engineering and failure exercises","Cost optimization and capacity budgets","Production incidents, on-call practice, and postmortems"]},{id:"email-reliability",title:"Email infrastructure and recovery",stage:"11 \xb7 Production",summary:"Make email delivery trustworthy through authentication, feedback, and recovery.",status:"planned",topics:["SMTP and delivery lifecycle","SPF, DKIM, and DMARC","Bounces, complaints, and suppression","Provider failover and rate control","RTO, RPO, and incident runbooks"]},{id:"fde-delivery",title:"Forward deployed engineering",stage:"12 \xb7 Delivery",summary:"Translate a customer problem into an integrated, measurable production outcome.",status:"planned",topics:["Discovery and problem framing","Integration and data constraints","Pilot scope and acceptance criteria","Deployment, handoff, and support","Outcome measurement and iteration"]}]}},2704:()=>{},5644:(a,b,c)=>{Promise.resolve().then(c.t.bind(c,1921,23)),Promise.resolve().then(c.t.bind(c,440,23)),Promise.resolve().then(c.t.bind(c,4342,23)),Promise.resolve().then(c.t.bind(c,2265,23)),Promise.resolve().then(c.t.bind(c,5421,23)),Promise.resolve().then(c.t.bind(c,1335,23)),Promise.resolve().then(c.t.bind(c,664,23)),Promise.resolve().then(c.bind(c,4661))},6487:()=>{},8046:()=>{},8335:()=>{},8796:(a,b,c)=>{Promise.resolve().then(c.t.bind(c,5547,23)),Promise.resolve().then(c.t.bind(c,5098,23)),Promise.resolve().then(c.t.bind(c,7644,23)),Promise.resolve().then(c.t.bind(c,3859,23)),Promise.resolve().then(c.t.bind(c,8099,23)),Promise.resolve().then(c.t.bind(c,6237,23)),Promise.resolve().then(c.t.bind(c,8562,23)),Promise.resolve().then(c.t.bind(c,6675,23))},9489:(a,b,c)=>{"use strict";c.d(b,{B:()=>d,H:()=>e});let d={"ml-foundations":{id:"ml-foundations",title:"ML foundations",summary:"Understand the learning problem, data, training, evaluation, and production boundary before choosing a model.",level:"Foundation",index:"README.md",lessons:[{id:"what-ml-solves",title:"What machine learning solves",file:"01-what-ml-solves.md"},{id:"data-and-splits",title:"Data, labels, and trustworthy splits",file:"02-data-and-splits.md"},{id:"training-mechanics",title:"Loss, parameters, and gradient descent",file:"03-training-mechanics.md"},{id:"evaluation",title:"Evaluation and decision thresholds",file:"04-evaluation.md"},{id:"inference-and-monitoring",title:"Inference, monitoring, and review",file:"05-inference-and-monitoring.md"}]},"async-systems":{id:"async-systems",title:"Queues and reliable delivery",summary:"Start with what a queue is and when to use one, then design work that survives retries, duplicates, overload, and partial failure.",level:"Systems",index:"README.md",assets:["queue-mark.svg","queue-basics.svg","acceptance.svg","backpressure.svg","retries.svg","idempotency.svg","outbox-events.svg","delivery-channels.svg","operations.svg"],lessons:[{id:"what-is-a-queue",title:"What a queue is and when to use one",file:"00-what-is-a-queue.md"},{id:"queue-boundary",title:"The queue boundary and worker contract",file:"01-queue-boundary.md"},{id:"backpressure",title:"Capacity, backpressure, and scheduling",file:"02-backpressure.md"},{id:"retries-and-dlq",title:"Timeouts, retries, and dead-letter queues",file:"03-retries-and-dlq.md"},{id:"idempotency",title:"Idempotency and delivery guarantees",file:"04-idempotency.md"},{id:"events-and-sagas",title:"Events, outbox, and sagas",file:"05-events-and-sagas.md"},{id:"delivery-channels",title:"Webhooks, live updates, and scheduled jobs",file:"06-delivery-channels.md"},{id:"operations",title:"Operating and reviewing a delivery system",file:"07-operations.md"}]},"scale-design":{id:"scale-design",title:"Scale and system design",summary:"Start with a single request, then design capacity, traffic, storage, consistency, and safe change for a growing service.",level:"Systems",index:"README.md",assets:["scale-mark.svg","system-map.svg","requirements.svg","capacity.svg","scaling.svg","api-boundary.svg","caching.svg","queries.svg","replication.svg","consistency.svg","concurrency.svg","compatibility.svg","logo-nginx.svg","logo-postgresql.svg","logo-redis.svg","logo-kubernetes.svg","logo-cloudflare.svg","logo-prometheus.svg","logo-grafana.svg","logo-opentelemetry.svg","logo-k6.svg","logo-flyway.svg","logo-envoyproxy.svg","logo-openapiinitiative.svg","logo-fastapi.svg","logo-sqlalchemy.svg"],lessons:[{id:"system-design-basics",title:"What system design solves",file:"00-system-design-basics.md"},{id:"capacity-and-latency",title:"Capacity, throughput, and tail latency",file:"01-capacity-and-latency.md"},{id:"scaling-and-balancing",title:"Scaling and load balancing",file:"02-scaling-and-balancing.md"},{id:"edge-and-api-boundary",title:"The edge and API boundary",file:"03-edge-and-api-boundary.md"},{id:"caching-and-invalidation",title:"Caching and invalidation",file:"04-caching-and-invalidation.md"},{id:"queries-and-connections",title:"Queries, indexes, and connections",file:"05-queries-and-connections.md"},{id:"replication-and-sharding",title:"Replication, partitioning, and sharding",file:"06-replication-and-sharding.md"},{id:"consistency-and-time",title:"Consistency, partitions, and time",file:"07-consistency-and-time.md"},{id:"concurrency-and-runtime",title:"Concurrency, locks, and runtime health",file:"08-concurrency-and-runtime.md"},{id:"compatibility-and-review",title:"Compatible change and architecture review",file:"09-compatibility-and-review.md"}]}},e={"ml-foundations":{"README.md":"# ML foundations\n\nMachine learning (ML) is a way to make predictions by learning patterns from examples. A traditional program follows rules written by a developer; an ML model uses patterns it learned from data to make a prediction about a new case. This module begins with that idea, then shows how to prepare examples, test whether predictions are useful, and operate a model safely. You do not need a deep-learning framework or advanced calculus.\n\n## Start here: what is machine learning?\n\nSuppose a support team has thousands of past tickets labeled **billing**, **access**, or **technical**. A model can learn from those labeled tickets and suggest a category for a new ticket. That suggestion is a **prediction**. The past tickets are **training data**; the ticket's words and available metadata are **features**; the correct category is a **label**. A person or simple rule can still review the result.\n\nML is useful when the pattern is too varied to express as a small set of maintainable rules and you can check the outcome. It is a poor replacement for a fixed policy such as “only the account owner may download a file.” Experienced readers should use the first lesson to check the problem definition and baseline before moving to data quality and evaluation.\n\n## Who this is for\n\nPeople new to ML and software engineers building or reviewing a model-backed feature. The first lesson defines the essential terms. Basic programming and API knowledge help with the later serving examples; you can work through the early exercises with a spreadsheet or a small script.\n\n## What you will be able to do\n\n- Turn a vague request into a prediction target, available inputs, and a non-ML baseline.\n- Distinguish features from labels and training from inference.\n- Choose a split that tests the way the model will be used, and recognize data leakage.\n- Explain what loss, parameters, hyperparameters, and gradient descent do.\n- Read a confusion matrix, choose a threshold from error costs, and plan a safe serving path.\n\n## Learning approach\n\nUse one public example throughout: **route incoming support tickets** to a billing, access, or technical queue. Each ticket has text and metadata. Historical tickets have a final queue assigned by a human. A model may predict a queue, but a person can correct it. The example is deliberately small so you can reason about the complete system before adding a complex model.\n\nRead in order. After each lesson, complete its **Try it** section before opening the next page. Keep one short design note with your target, data contract, baseline, evaluation set, threshold, and rollout decision. The note is the module's final artifact.\n\n## Diagram: the complete learning path\n\nThis workflow joins the five lessons: define a decision and baseline, prepare examples, reserve a future-like holdout, train, evaluate error costs, and serve a monitored decision. Use it as a map while reading; each lesson also contains a smaller diagram of its own step. Open the diagram in a separate tab to inspect its paths and export it.\n\n\x3c!-- ML_LIFECYCLE_DIAGRAM --\x3e\n\n## Lesson index\n\n| Order | Lesson | Question it answers |\n| --- | --- | --- |\n| 1 | [What machine learning solves](/learn/ai-engineer-fde/ml-foundations/what-ml-solves) | When is learning from examples better than explicit rules? |\n| 2 | [Data, labels, and trustworthy splits](/learn/ai-engineer-fde/ml-foundations/data-and-splits) | Will the evaluation represent future use? |\n| 3 | [Loss, parameters, and gradient descent](/learn/ai-engineer-fde/ml-foundations/training-mechanics) | What changes when a model learns? |\n| 4 | [Evaluation and decision thresholds](/learn/ai-engineer-fde/ml-foundations/evaluation) | Which errors are acceptable for this product? |\n| 5 | [Inference, monitoring, and review](/learn/ai-engineer-fde/ml-foundations/inference-and-monitoring) | How does a tested model become a safe feature? |\n\n## Completion check\n\nYou are ready to move on when you can explain your feature without a model name: **input at prediction time → predicted output → baseline → held-out evaluation → human or automatic action → monitoring and rollback**. If any arrow is vague, return to the relevant lesson. More model complexity will not repair a missing data or decision contract.\n\n## Primary references\n\n- [Google Machine Learning Crash Course](https://developers.google.com/machine-learning/crash-course/) for the core ML concepts and exercises.\n- [Google's production ML systems module](https://developers.google.com/machine-learning/crash-course/production-ml-systems) for the boundary between an offline model and a running product.\n","01-what-ml-solves.md":"# What machine learning solves\n\nMachine learning starts with examples. During **training**, software finds a pattern in those examples and stores it in a **model**. During **inference**, that model uses the pattern to predict an answer for a new example. This lesson defines the basic parts, then asks whether a learned model is useful for a particular decision.\n\n## The four pieces of a first model\n\nImagine a ticket that says, “I cannot sign in.” We want to suggest **access** as its support queue.\n\n| Piece | Plain meaning | Ticket example |\n| --- | --- | --- |\n| Example | One case used to learn or test | One past support ticket |\n| Feature | Information available when predicting | Ticket text and product area |\n| Label | The answer attached to a past example | Final reviewed queue: access |\n| Model | A learned mapping from features to predictions | Software that suggests a queue for a new ticket |\n\nThe model is not the same as the training data, and its prediction is not automatically correct. A professional review asks whether the examples represent future tickets, whether the label is trustworthy, and what happens when a prediction is wrong. Later lessons test those questions explicitly.\n\n## Start with the decision\n\nImagine an inbox of support tickets. A person currently reads each ticket and assigns it to **billing**, **access**, or **technical** support. The desired behavior is not “use AI.” It is “route routine tickets accurately enough to reduce waiting time while preserving a correction path.” That statement gives us a target, a user benefit, and a failure to watch for.\n\nThe input available **at routing time** may include the subject, message text, selected product area, and language. The final human-assigned queue is a possible label. A model predicts the label from the inputs. A rule-based alternative might route messages containing “refund” to billing and everything else to a general queue. That simple rule is the **baseline**: a comparison point that may be cheap, understandable, and already good enough.\n\nUse a model when the pattern is too varied for maintainable rules, representative examples exist, the outcome can be checked, and the expected benefit justifies the cost of training and operating it. Prefer explicit code when the decision is a policy or invariant, such as “only an account owner may download this invoice.” Learning from examples must not replace authorization.\n\n## The three common learning shapes\n\n| Shape | What the examples provide | Ticket example | Output |\n| --- | --- | --- | --- |\n| Supervised classification | A category label for each example | Historical tickets with final queues | Billing, access, or technical |\n| Supervised regression | A numeric target | Historical tickets with resolution time | Estimated hours to resolve |\n| Unsupervised learning | No target label | Unlabeled ticket text | Groups of similar tickets |\n\n“Supervised” does not mean a human watches every training step. It means the training examples carry target answers. “Unsupervised” does not mean the result needs no review. A cluster may reflect language or writing style instead of the business issue you wanted to discover.\n\n## Training and inference are different operations\n\nDuring **training**, software compares predictions with known labels and adjusts model parameters. During **inference**, a deployed model uses its current parameters to predict on a new ticket. Training can happen offline; inference is usually on the product's request or job path. The inputs available in these two environments must match. A field added after a ticket is resolved cannot be used to predict where the ticket should go when it first arrives.\n\n## Diagram: training and inference paths\n\n```aosdf-diagram\nHistorical tickets + final queues ──▶ train ──▶ versioned classifier\n                                                    │\nNew ticket at arrival ──────────────────────────────┴──▶ predict queue\n                                                          │\n                                               rule / human review / correction\n```\n\nThe diagram has two paths because a working application has both a way to produce a model and a way to use it. The correction path provides feedback; it does not mean that every correction should be fed back into training without review.\n\n[Explore the full ML lifecycle diagram](/ml-foundations-lifecycle.archify.html) to see where this distinction fits in the complete workflow.\n\n## Worked decision\n\nSuppose 1,000 tickets are routed each day. The keyword baseline routes 700 automatically and sends 300 to a person. A proposed classifier might route 900 automatically, but the extra 200 are useful only if misrouted tickets do not create more delay or expose private data. Before collecting data, decide what error rate and review policy would make the change worthwhile.\n\nThis is why “the model is 95% accurate” is not yet an engineering answer. You still need to know the class balance, which tickets were wrong, what the baseline achieved, and what happens to a wrong prediction.\n\n## Try it\n\nWrite a five-line feature brief for a task you know:\n\n1. **User decision:** what will the prediction help someone do?\n2. **Inputs:** what exists at the moment of prediction?\n3. **Target:** what answer can past examples supply?\n4. **Baseline:** what simple rule or existing process will you compare against?\n5. **Failure handling:** who can correct or override an error?\n\nIf line 2 uses information only known later, the proposed feature has a data-leakage problem. If line 3 cannot be observed reliably, the model may not be measurable.\n\n## Check your understanding\n\n- Why is a rule for account ownership a poor candidate for machine learning?\n- What changes during training that does not normally change during inference?\n- Why might grouping unlabeled tickets produce a useless business result?\n\n**Answer guide:** authorization is a deterministic policy; training adjusts parameters; unsupervised groups need to be interpreted against the actual business question.\n\n## Read further\n\n- [Google ML Crash Course: Introduction to ML](https://developers.google.com/machine-learning/intro-to-ml)\n- [Google ML Crash Course: Classification](https://developers.google.com/machine-learning/crash-course/classification)\n","02-data-and-splits.md":"# Data, labels, and trustworthy splits\n\nA model can look impressive in a test and fail in production because the test did not represent future use. This lesson treats the dataset as a product contract: what was known, how the answer was recorded, and how unseen examples will differ.\n\n## Define one example precisely\n\nFor ticket routing, one **example** is the ticket as it looked when it arrived. Its **features** may be the subject, body, language, and product area. Its **label** is the final queue chosen after review. A field such as “team that solved it” is not an input feature if it is only created after routing. A feature is useful only when it exists, with the same meaning, at inference time.\n\nLabels can be noisy. A ticket may be transferred among teams, or an agent may select a convenient category rather than the best one. Write a label policy: use the final resolving queue, the first accepted queue, or a reviewed category? These choices define different learning problems. Sample and audit labels before choosing a model.\n\n## Split for the future you expect\n\nUse a **training set** to fit parameters, a **validation set** to compare versions or thresholds, and a **test set** for a final check after choices are made. Repeatedly tuning against the test set turns it into another validation set. Keep it separate until the candidate and decision rule are fixed.\n\nA random row split is not always appropriate. If many tickets from the same customer or incident have near-identical text, copies in train and test make the test easier than future unseen customers. If product vocabulary changes over time, a later time window is more realistic than a random sample from the same period. The split unit should match the expected generalization claim.\n\n## Diagram: preparing evidence for evaluation\n\n```aosdf-diagram\nRaw tickets ──▶ deduplicate / audit labels ──▶ group or time split\n                                                  ├──▶ training: fit\n                                                  ├──▶ validation: choose\n                                                  └──▶ test: final estimate\n```\n\nThe diagram separates **data cleaning** from **model selection**. A clean split is not a substitute for representative data; the test distribution should still resemble the people and requests the feature will serve.\n\n[Explore the full ML lifecycle diagram](/ml-foundations-lifecycle.archify.html) to follow the data from the decision through the held-out evaluation.\n\n## Recognize leakage\n\n**Target leakage** occurs when a feature contains the answer or information unavailable at prediction time. In our example, including “assigned team after escalation” may make accuracy look extraordinary. **Duplicate leakage** occurs when the same case, or near-identical copies, appear across splits. **Process leakage** can arise when labels and features were both influenced by a prior routing rule; the model may simply learn that rule's historical bias.\n\nBuild a small data card before training:\n\n| Field | Question to record |\n| --- | --- |\n| Source and consent | Where did these records come from, and may they be used for this purpose? |\n| Prediction-time availability | Is this field present before routing? |\n| Missingness | Which users or channels lack it? |\n| Label policy | Who assigned the answer, and can it be wrong? |\n| Split unit | Customer, incident, time, or individual ticket? |\n| Retention | When should raw text and derived features be deleted? |\n\n## Worked split\n\nSuppose the available dataset contains 20,000 tickets from January through June. A defensible first experiment might train on January–April, choose settings on May, and test once on June. If a large incident generated hundreds of nearly identical tickets across those months, group the incident so related examples cannot appear on both sides of a split. Report the size and class distribution of every set; a tiny access-support class may need separate error analysis.\n\n## Try it\n\nTake ten representative records and mark every candidate feature as **available at prediction**, **created later**, or **uncertain**. Draft a label policy. Choose a split strategy and write one sentence explaining the future situation it tests. List two ways the measured score could still overstate production quality.\n\n## Check your understanding\n\n- Why is “the team that resolved the ticket” dangerous as an input feature?\n- When is a time-based or grouped split preferable to a random row split?\n- What happens if you compare model versions on the test set every day?\n\n**Answer guide:** the feature may only exist after the prediction; grouped or time splits test unseen entities or future changes; repeated test use leaks selection into the final estimate.\n\n## Read further\n\n- [Google ML Crash Course: Dividing datasets](https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets)\n- [Google ML Crash Course: Overfitting](https://developers.google.com/machine-learning/crash-course/overfitting/overfitting)\n","03-training-mechanics.md":"# Loss, parameters, and gradient descent\n\nA model learns by changing numbers that influence its predictions. This lesson explains that loop with one small calculation. You do not need to implement an optimizer to review a model-backed feature, but you should know what was learned, what was chosen by an engineer, and why a low training error can mislead.\n\n## A model is a function with adjustable parameters\n\nFor a simple numeric prediction, write `prediction = weight \xd7 input + bias`. The **weight** and **bias** are parameters. Training changes them. The form of the function is the model family; its capacity determines which patterns it can represent. A ticket classifier uses more features and returns scores for billing, access, and technical queues, but it follows the same idea: inputs pass through a parameterized function to produce a prediction.\n\nThe **loss** measures how wrong a prediction is on an example. For a numeric target, squared error is `(prediction − target)\xb2`. For classification, a loss such as cross-entropy penalizes assigning low probability to the correct class. Loss is a training signal, not a complete product success metric. An average loss can hide errors on a small but important group.\n\n## Follow one update\n\nSuppose `input = 2`, `target = 4`, `weight = 1`, and `bias = 0`. The prediction is `2`; squared error is `4`. Holding the bias fixed, the gradient of this example's loss with respect to the weight is `2 \xd7 (prediction − target) \xd7 input = −8`. With learning rate `0.1`, one gradient step gives `new weight = 1 − 0.1 \xd7 (−8) = 1.8`. The new prediction is `3.6`; squared error is `0.16`.\n\nThis is a teaching calculation for one example, not evidence that a model generalizes. In real training, updates use many examples, and a step that improves one can hurt another. The **learning rate** is a hyperparameter chosen before or during the run. If it is too large, updates can overshoot; if too small, progress can be slow. Other hyperparameters include regularization strength and model size.\n\n## Diagram: parameter updates and release boundary\n\n```aosdf-diagram\nTraining batch ──▶ predictions ──▶ loss against labels ──▶ gradients\n       ▲                                              │\n       └──────────── updated parameters ◀────────────┘\n                              │\n                     frozen, versioned model ──▶ inference\n```\n\nThe lower path matters operationally: serving should use a known model version. Retraining produces a new candidate; it does not silently alter the model used for every live request.\n\n[Explore the full ML lifecycle diagram](/ml-foundations-lifecycle.archify.html) to see where a trained model enters evaluation and serving.\n\n## Watch training and validation together\n\nIf training loss falls while validation loss rises, the model may be fitting details peculiar to the training set. This is **overfitting**. It can also signal a split or distribution problem, so inspect examples before changing architecture. First responses include more representative data, a simpler model, regularization, or stopping training earlier. A large model is not automatically the best baseline.\n\nFor ticket routing, begin with a keyword rule, then a simple text classifier. Track both against the same held-out tickets. A neural model is worth considering only when the simpler candidates miss a valuable pattern and the added operating cost is justified.\n\n## Try it\n\n1. Recalculate the worked example with learning rate `0.25`. What is the new weight and loss?\n2. Draw training and validation loss curves where validation begins to rise. Mark the model version you would consider keeping.\n3. List the parameters and two hyperparameters for a simple classifier. Explain which are learned from examples.\n\n## Check your understanding\n\n- Does a lower training loss prove that ticket routing improved for future tickets?\n- What is the difference between a model parameter and a learning rate?\n- Why should a retraining run create a new model version?\n\n**Answer guide:** with learning rate `0.25`, weight becomes `3`, prediction becomes `6`, and squared error returns to `4`; the step overshot. A lower training loss proves only better fit to training examples. Parameters are updated from data; learning rate controls the update. Versioning supports comparison and rollback.\n\n## Read further\n\n- [Google ML Crash Course: Gradient descent](https://developers.google.com/machine-learning/crash-course/linear-regression/gradient-descent)\n- [Google ML Crash Course: Overfitting](https://developers.google.com/machine-learning/crash-course/overfitting/overfitting)\n","04-evaluation.md":"# Evaluation and decision thresholds\n\nEvaluation asks whether a candidate improves the decision that people actually care about. A single score rarely answers that question. This lesson uses a held-out set, a confusion matrix, and an explicit action policy.\n\n## Compare with the baseline on the same cases\n\nTake the test set reserved in the data lesson. Run the existing keyword rule and the candidate model on exactly those tickets. Record the data version, model version, label policy, and threshold before looking at results. The comparison should include the work created by mistakes, not just the number of correct labels.\n\nFor a simple binary decision, consider “send to access support” as the positive class. On 100 held-out tickets, suppose the model produces this table:\n\n| | Actually access | Actually another queue |\n| --- | ---: | ---: |\n| Predicted access | 18 true positives | 2 false positives |\n| Predicted other | 7 false negatives | 73 true negatives |\n\n**Precision** is `18 / (18 + 2) = 0.90`: of tickets sent to access, 90% belonged there. **Recall** is `18 / (18 + 7) = 0.72`: the model found 72% of access tickets. **Accuracy** is `(18 + 73) / 100 = 0.91`. Accuracy sounds high while 7 of 25 access tickets are missed. Which metric matters depends on the cost of a wrong destination. Repeat the analysis for each class in a three-queue classifier.\n\n## A score needs a decision rule\n\nA classifier can return a score or probability-like output. A **threshold** turns that output into an action. Raising the threshold for automatic routing generally reduces uncertain automatic decisions; it can improve precision while reducing recall. The exact tradeoff must be measured on validation data. If scores are interpreted as probabilities, check calibration before making claims such as “90% confidence means 90% chance.”\n\nAn example policy is: route automatically only when the highest class score clears a tested threshold and exceeds the second highest by a tested margin; otherwise place the ticket in a review queue. Evaluate the full policy, including review volume and delay, against the baseline. Do not tune the threshold on the final test set.\n\n## Diagram: from held-out cases to action policy\n\n```aosdf-diagram\nHeld-out cases ──▶ baseline + candidate predictions ──▶ error table\n                                                       │\n                       error cost + review capacity ◀──┘\n                                  │\n                       threshold + human review policy\n                                  │\n                        final untouched test check\n```\n\n[Explore the full ML lifecycle diagram](/ml-foundations-lifecycle.archify.html) to place the threshold and review policy within the release path.\n\n## Inspect the mistakes\n\nBreak results down by queue, language, input channel, and recent time period when sample sizes allow. Read actual false positives and false negatives. A model might perform well overall because one common queue dominates while failing on a less common queue. Report group sizes alongside rates; tiny slices have high uncertainty. For numeric predictions, compare mean absolute error against a simple constant or rule baseline, then inspect the tail of large errors.\n\n## Try it\n\n1. Compute precision, recall, and accuracy from the table without looking at the formulas above.\n2. Write the cost of one false positive and one false negative for a routing workflow. Which would you try to reduce first?\n3. Specify an automatic-route rule and a review path. State which set you would use to choose its threshold and which set you would use once for the release estimate.\n\n## Check your understanding\n\n- Why can 91% accuracy hide a weak experience for access tickets?\n- What happens to the final test estimate if you repeatedly tune a threshold against it?\n- Why must a “high confidence” score be checked for calibration?\n\n**Answer guide:** the access class has 7 misses among 25 true cases; repeated test tuning makes the test part of model selection; raw scores may not match observed frequencies. Choose the policy on validation data, then evaluate once on test data.\n\n## Read further\n\n- [Google ML Crash Course: Accuracy, precision, and recall](https://developers.google.com/machine-learning/crash-course/classification/accuracy-precision-recall)\n- [Google ML Crash Course: Thresholds and the confusion matrix](https://developers.google.com/machine-learning/crash-course/classification/thresholding)\n","05-inference-and-monitoring.md":"# Inference, monitoring, and review\n\nAn offline result becomes a product only when a new input can receive a timely, traceable decision and people can detect and correct failures. This lesson connects the model to a serving contract, a cautious release, and a feedback loop.\n\n## Define the serving contract\n\nFor ticket routing, the request contains a ticket ID and the fields allowed at arrival. Validate their schema and size before inference. The response contains a proposed queue, model version, decision score, and whether automatic routing is allowed. Keep a human review path for low scores or invalid inputs. The prediction service should not acquire authority to read unrelated tickets merely because the model needs context.\n\nTraining and serving transformations must agree. If training lowercases text and serving does not, the model sees a different input representation. Record the feature schema and preprocessing version with the model artifact. Keep a known fallback, such as the original keyword rule or manual triage, available during failures.\n\n## Diagram: serving and feedback loop\n\n```aosdf-diagram\nNew ticket ──▶ schema + privacy checks ──▶ feature transform ──▶ model version\n                                                                   │\n                                  review queue ◀── decision gate ◀──┘\n                                       │                 │\n                                 human correction   approved route\n                                       └────────┬────────┘\n                                                ▼\n                                  delayed outcomes + monitoring\n```\n\nThe decision gate belongs in application code. A model proposes; the product policy decides whether to act. Corrections are evidence for later analysis, not an instruction to retrain immediately on every click.\n\n[Explore the full ML lifecycle diagram](/ml-foundations-lifecycle.archify.html) to trace how serving follows an evaluated release decision.\n\n## Release in controlled steps\n\nFirst replay historical held-out cases through the real serving code to catch feature and serialization mistakes. Next, use a **shadow** run: make predictions on live tickets without affecting routing, then compare with the eventual human decision. A limited **canary** can route a small eligible slice automatically while the rest use the existing path. Expand only if error, latency, and review-volume limits hold. Preserve a switch that returns traffic to the baseline and retain the previous model artifact.\n\nFor the ticket example, a release note might say: “Only English billing and technical tickets with a validated input schema and a score above the chosen threshold are eligible. All others go to human triage. Stop the canary if misroutes exceed the agreed rate or p95 inference latency exceeds the budget.” The actual limits must come from the service's needs and measured baseline.\n\n## Monitor what the product can observe\n\nMeasure request volume, validation failures, serving errors, latency, fallback use, predicted-class mix, and review volume immediately. Measure routing quality when corrected labels arrive. Changes in input or prediction distribution can suggest drift, but they do not by themselves prove that accuracy changed. Investigate with labeled examples. Segment metrics by channel and language where the samples are large enough.\n\nLog the minimum needed for debugging: request ID, timestamp, model and feature versions, decision, and outcome reference. Set access and retention rules for ticket text. A trace should help reconstruct a decision without storing sensitive content in every log.\n\n## Produce a release-ready design note\n\nYour final artifact for this module should fit on one or two pages:\n\n1. **Decision and baseline:** what changes for a user, and what currently handles it?\n2. **Data contract:** prediction-time fields, label policy, exclusions, and split rationale.\n3. **Candidate and evaluation:** model/version, baseline comparison, confusion matrices or error distribution, and important slices.\n4. **Action policy:** threshold, human review, and forbidden automatic actions.\n5. **Serving and release:** schema, latency budget, shadow/canary plan, fallback, and rollback owner.\n6. **Monitoring:** immediate service signals, delayed quality signals, and a correction review cadence.\n\nIf any part cannot be stated, keep the existing process while you gather evidence. A more capable model does not remove the need for a clear decision and an observable release.\n\n## Try it\n\nDraft the six-part note for the ticket example or another low-risk feature. Identify one signal that appears immediately and one that appears only after human review. Write the exact action an operator can take if the model begins misrouting tickets.\n\n## Check your understanding\n\n- Why is a shadow run useful even after offline evaluation?\n- Can a shift in predicted classes prove that quality has declined?\n- What must be versioned to explain a particular production prediction?\n\n**Answer guide:** shadowing exercises the live input and serving path without changing user outcomes; distribution shift is a warning, not a quality label; retain the model, feature transformation, input schema, and decision policy versions. Roll back to the baseline if the release gate fails.\n\n## Read further\n\n- [Google ML Crash Course: Monitoring ML systems](https://developers.google.com/machine-learning/crash-course/production-ml-systems/monitoring)\n- [Google ML Crash Course: Production ML systems](https://developers.google.com/machine-learning/crash-course/production-ml-systems)\n"},"async-systems":{"README.md":"# Queues and reliable delivery\n\nA queue is a place to hold work until a worker is ready to process it. For example, a website can accept a document export request, put an export job in a queue, and let a background worker create the file while the user continues using the site. This module begins with that basic flow, then explains the failure and scaling decisions needed to run it reliably.\n\n## Start here: what is a queue?\n\nThink of a queue as a waiting line for tasks. A **producer** adds a message describing a task; a **worker** (also called a consumer) takes a message and performs it. The queue is usually managed by a **broker** or queue service. Unlike a person waiting in line, the website can respond before the task is finished. That is **asynchronous processing**.\n\n![A user asks for an export; the API produces a job, the queue holds it, and a worker creates the file.](/learning/async-systems/queue-basics.svg)\n\n```aosdf-diagram\nUser request ──▶ API (producer) ──▶ Queue ──▶ Worker (consumer) ──▶ Finished export\n                    │\n                    └──▶ returns an operation ID so the user can check progress\n```\n\nQueues are useful when work is slow, can happen later, arrives in bursts, or needs independent retries. Common examples include document exports, image processing, email delivery, and importing files. A queue adds moving parts, so a short, fast operation that must finish before a response may be simpler as a direct call. A queue alone does not guarantee a task runs once, finishes in order, or succeeds; the later lessons show how to define those promises.\n\n## Who this is for\n\nPeople new to background jobs and engineers building or reviewing event consumers, scheduled tasks, webhooks, or live progress updates. The first lesson assumes only basic familiarity with a website request. Later lessons use HTTP and database transactions, defining the queue terms as they appear. No specific broker is required; the examples use an at-least-once queue such as an Amazon SQS standard queue, and provider-specific behavior is called out where relevant.\n\n## What you will be able to do\n\n- Explain what a queue, producer, message, and worker do, and when a queue is useful.\n- Define what an API promises when it accepts asynchronous work and how a client checks completion.\n- Write a job contract with an operation ID, version, owner, attempt policy, and safe acknowledgement point.\n- Estimate queue growth and choose backpressure before overload damages downstream services.\n- Classify failures, set timeouts and retry budgets, quarantine poison messages, and plan replay.\n- Prevent a duplicate delivery from repeating an external effect.\n- Choose between a work queue, pub/sub event, outbox, saga, webhook, or browser update based on the communication contract.\n- Operate the system with queue age, result state, tracing, alerts, and a recovery runbook.\n\n## Learning approach\n\nFollow one general example: a user requests a **document export**. The API records an export operation and returns `202 Accepted` with its ID. A worker creates a file and marks the operation complete. The UI polls or receives a progress update. If generation fails, the user should see an honest status and an operator should be able to diagnose or replay the job safely.\n\nIf queues are new to you, read [What a queue is and when to use one](/learn/ai-engineer-fde/async-systems/what-is-a-queue) before the engineering contracts. If you already operate workers, use that lesson to check your vocabulary and move into the failure cases. After each **Try it**, add one section to a short design note: queue choice, request contract, job schema, capacity estimate, retry table, idempotency rule, event boundary, and runbook. The final lesson checks that these sections agree.\n\n## Diagram: the delivery and recovery path\n\nThe main path records intent, publishes work, claims a job, applies an effect, and acknowledges completion. A transient failure follows a bounded retry path; repeated failures move to a dead-letter queue for inspection. The diagram is a teaching model: a real system must also handle a worker crash between the effect and acknowledgement.\n\n![The API records an operation, sends it to a queue, and a worker creates a result after returning a status ID to the user.](/learning/async-systems/acceptance.svg)\n\n\x3c!-- QUEUE_LIFECYCLE_DIAGRAM --\x3e\n\n## Lesson index\n\n| Order | Lesson | Question it answers |\n| --- | --- | --- |\n| 1 | [What a queue is and when to use one](/learn/ai-engineer-fde/async-systems/what-is-a-queue) | What waits in a queue, who processes it, and why use one? |\n| 2 | [The queue boundary and worker contract](/learn/ai-engineer-fde/async-systems/queue-boundary) | What does accepting work promise, and when may a worker acknowledge it? |\n| 3 | [Capacity, backpressure, and scheduling](/learn/ai-engineer-fde/async-systems/backpressure) | What happens when arrivals outrun workers? |\n| 4 | [Timeouts, retries, and dead-letter queues](/learn/ai-engineer-fde/async-systems/retries-and-dlq) | Which failures deserve another attempt? |\n| 5 | [Idempotency and delivery guarantees](/learn/ai-engineer-fde/async-systems/idempotency) | How can duplicate deliveries avoid duplicate effects? |\n| 6 | [Events, outbox, and sagas](/learn/ai-engineer-fde/async-systems/events-and-sagas) | How do services publish facts and coordinate partial work? |\n| 7 | [Webhooks, live updates, and scheduled jobs](/learn/ai-engineer-fde/async-systems/delivery-channels) | Which channel fits a recipient or timing need? |\n| 8 | [Operating and reviewing a delivery system](/learn/ai-engineer-fde/async-systems/operations) | How do we know work is moving and recover it safely? |\n\n## Completion check\n\nExplain one export request from acceptance through a successful result, a duplicate delivery, an unavailable file store, and a poison job. Name the durable record, acknowledgement point, effect deduplication rule, queue-age alert, and manual replay procedure. If one is undefined, the architecture is not ready to rely on.\n\n## Primary references\n\n- [Amazon SQS standard queue semantics](https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/standard-queues.html)\n- [Amazon SQS visibility timeout](https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-visibility-timeout.html)\n- [AWS decision guide: SQS, SNS, or EventBridge](https://docs.aws.amazon.com/decision-guides/latest/decision-guides/sns-or-sqs-or-eventbridge.html)\n","00-what-is-a-queue.md":"# What a queue is and when to use one\n\nYou click **Export document**. Creating the file may take a minute, but the website can respond immediately: “Your export has started.” How can it finish the work after the response? It can place an export job in a **queue** for a background worker to process.\n\n## The basic idea\n\nA queue holds messages representing work that has not yet been completed. One part of a system **produces** a message; another part **consumes** it. A queue service, often called a **broker**, stores and delivers messages between them. The producer and consumer do not have to run at the same time or at the same speed.\n\n| Term | Plain meaning | Export example |\n| --- | --- | --- |\n| Producer | Adds work | The export API |\n| Message or job | A description of work | “Generate export `exp_82`” |\n| Queue or broker | Holds and delivers waiting work | An export-jobs queue |\n| Consumer or worker | Takes work and performs it | A process that creates the file |\n| Result store | Records what happened | An export status row and file reference |\n\nThe queue normally holds a **small instruction or reference**, not the entire document. The worker uses the export ID to load the current inputs and records the result where the website can find it. The queue and the result store have different jobs: the queue transports work; the result store answers “what happened to my export?”\n\n## Diagram: one request, two paths\n\n![An export request enters an API, an export job waits in a queue, and a worker creates the file while the user continues.](/learning/async-systems/queue-basics.svg)\n\n```aosdf-diagram\nUser ──▶ Export API ──▶ Queue ──▶ Worker ──▶ File + completed status\n           │\n           └──▶ “Started: exp_82” ──▶ User checks status later\n```\n\nThe upper path performs the work in the background. The lower path lets the user continue without waiting for file creation. [Open the full delivery and recovery diagram](/queue-delivery-lifecycle.archify.html) when you are ready to inspect failures and acknowledgements.\n\n## Why use a queue?\n\n**Keep slow work off the request path.** If a file takes a minute to generate, keeping the browser request open can time out or tie up server capacity. The API can return an operation ID after it has safely accepted the request.\n\n**Absorb short bursts.** If 200 people request exports at once and workers can handle 20 at a time, the queue holds the rest. This buys time; it does not increase processing capacity. If arrivals stay high, waiting time grows, as lesson 3 calculates.\n\n**Separate responsibilities.** The API handles validation and acceptance; workers handle file creation. They can be deployed and scaled independently. A worker failure does not have to erase an accepted request, provided the job and its state are stored durably.\n\n**Retry uncertain failures.** A worker can try again after a temporary file-store outage. Repeating work may also repeat an effect, so later lessons add bounded retries and idempotency.\n\nQueues also help with image processing, email delivery, imports, and scheduled jobs. The same concept can connect services, though a **work queue** and **publish-subscribe event** have different ownership: one task needs a worker to complete it, while an event may inform several independent subscribers.\n\n## When is a direct call simpler?\n\nUse a direct request when the caller needs the result now, the work is consistently quick, and a separate failure or progress state would add unnecessary complexity. For example, checking whether a form field is valid usually belongs in the request. Use a queue when the user can receive an operation ID and come back for the result, or when a background task can safely proceed without holding the request open.\n\nAsk three questions before adding a queue:\n\n1. Can the caller continue without the completed result?\n2. Where will the caller see success or failure later?\n3. What happens if the same job is delivered again?\n\nIf you cannot answer the second question, the queue may hide failed work. If you cannot answer the third, retries may cause duplicate effects.\n\n## A first professional check\n\nThe waiting-line analogy is useful, but it has limits. Some brokers do not promise strict first-in-first-out order, and a message may be delivered again after a worker crash or lost acknowledgement. For example, Amazon SQS **standard queues** use at-least-once delivery and can deliver messages out of order. Define the exact guarantees your chosen broker provides, then make the worker safe when those guarantees are weaker than your business promise.\n\n## Try it\n\nChoose one task from **password check**, **generate a PDF**, **resize uploaded images**, and **show an account balance**. Decide whether the user needs an immediate result or can receive an operation ID. For a queued task, name its producer, message, queue, worker, and result store. Write the status the user sees if the worker fails.\n\n## Check your understanding\n\n- Does putting a job in a queue mean it has finished?\n- If a queue fills faster than workers process jobs, what grows?\n- Why should the result be stored outside the queue?\n- Does “first in line” always mean “first completed”?\n\n**Answer guide:** no, the job is waiting or being processed; backlog and waiting time grow; a status store makes the outcome queryable after the message is consumed; concurrent workers and broker semantics can change completion order.\n\n## Read further\n\n- [AWS decision guide: SQS, SNS, or EventBridge](https://docs.aws.amazon.com/decision-guides/latest/decision-guides/sns-or-sqs-or-eventbridge.html)\n- [Amazon SQS standard queues and delivery semantics](https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/standard-queues.html)\n","01-queue-boundary.md":'# The queue boundary and worker contract\n\nThe [first lesson](/learn/ai-engineer-fde/async-systems/what-is-a-queue) introduced a queue as a waiting place between a producer and a worker. The next question is what the website may promise when it places a job there. An asynchronous API acknowledges **acceptance**, not completion. In the document export example, a successful request means the operation was durably recorded and can be found again. It does not mean a file exists yet.\n\n## Model the states a user can observe\n\nA small state machine is enough: `accepted → running → succeeded`, with `failed` and `cancelled` as explicit exits. `GET /exports/{id}` returns status, a safe error code, and a file URL only after success. An unknown ID is different from a known failed export. A request with the same idempotency key should return the existing operation rather than create another export.\n\nThe API can return `202 Accepted` with `Location: /exports/{id}`. Return it only after the operation and a publishable intent are durable. If the database commit fails, return an error. If the queue publish is separate from the database commit, the outbox pattern in lesson 5 closes that gap.\n\n## Put a contract in each job\n\nThe broker message should point to durable business state; it need not carry an entire document or sensitive payload.\n\n```json\n{\n  "jobId": "job_82",\n  "operationId": "exp_82",\n  "tenantId": "tenant_7",\n  "type": "export.generate",\n  "version": 1,\n  "traceId": "trace_19"\n}\n```\n\n`jobId` identifies the delivery; `operationId` identifies the effect across deliveries. The worker checks that the tenant and operation still match, validates the schema version, and loads authorized source data from the system of record. Do not trust a message merely because it came from a queue: producers can be buggy or compromised, and old messages can outlive an authorization change.\n\n## Diagram: acceptance is separate from completion\n\n![The API durably records an operation and returns an ID; a queue then delivers work to a worker that records the finished result.](/learning/async-systems/acceptance.svg)\n\n```aosdf-diagram\nPOST /exports ──▶ commit operation + intent ──▶ 202 + operation ID\n                         │\n                         └──▶ queue ──▶ worker ──▶ file ──▶ status: succeeded\n                                            └──▶ failure ──▶ status: failed / retrying\n```\n\n[Explore the full queue delivery diagram](/queue-delivery-lifecycle.archify.html) to inspect the acknowledgement and recovery branches.\n\n## Acknowledge after the durable effect\n\nA worker claims a message, reads the current operation, performs or confirms the effect, durably records the result, then acknowledges the message. Acknowledging first can lose work if the worker crashes before recording the result. Acknowledging last can lead to redelivery if the acknowledgement is lost, which is why the effect must tolerate duplicates.\n\nFor SQS, a received message becomes temporarily invisible. If processing does not finish and delete the message within that visibility timeout, it can reappear; standard queues may also deliver more than once during the timeout. Other brokers use leases or acknowledgement mechanisms with their own details. Match the lease to expected work, extend it when supported, and still design for overlap.\n\n## Try it\n\nWrite the request and status response for an export. Specify the durable acceptance point, the message fields, the state transition that makes the file downloadable, and the exact step after which the worker acknowledges. Simulate a crash just before acknowledgement.\n\n## Check your understanding\n\n- Why does `202` need an operation ID and status URL?\n- What can happen if the worker acknowledges before writing the result?\n- Why is a visibility lease not a duplicate-prevention guarantee?\n\n**Answer guide:** the client needs a stable way to observe an unfinished operation; early acknowledgement can lose accepted work; a crash, timeout, or broker duplicate can cause another delivery.\n\n## Read further\n\n- [HTTP 202 Accepted, MDN](https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/202)\n- [Amazon SQS visibility timeout](https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-visibility-timeout.html)\n',"02-backpressure.md":"# Capacity, backpressure, and scheduling\n\nA queue absorbs a temporary mismatch between incoming work and worker capacity. It does not create capacity. If jobs arrive faster than they finish for long enough, the oldest job gets older until the promised completion time is missed.\n\n## Calculate the backlog before scaling\n\nSuppose export requests arrive at **120 jobs/minute** during a 20-minute peak. Six workers each complete **15 jobs/minute**, so service capacity is **90/minute**. Backlog grows at **30/minute**, reaching about **600 jobs** after 20 minutes. Once arrivals return to **60/minute**, spare capacity is **30/minute** and draining those 600 jobs takes another **20 minutes**. A 20-minute burst can therefore affect users for roughly 40 minutes.\n\nThese are simple averages. Real service times vary, large exports may dominate, and a shared file store can become slower as concurrency rises. Measure the oldest job age and completion latency, not only queue depth.\n\n## Choose an overload policy\n\nBefore increasing consumers, decide what the system should do at capacity:\n\n| Policy | When it helps | Cost |\n| --- | --- | --- |\n| Add workers | Downstream storage and quota have spare capacity | More concurrent load and cost |\n| Limit intake | Work can be refused or deferred honestly | Some requests get `429` or a clear busy response |\n| Prioritize | Some jobs have stronger deadlines | Low-priority starvation needs a limit |\n| Coalesce | Repeated requests ask for the same output | Requires a stable key and freshness rule |\n| Shed optional work | Secondary work is not required for completion | Product must accept reduced functionality |\n\nSet a maximum in-flight count per worker and a per-tenant quota. A broker prefetch or batch setting that hands one worker hundreds of slow jobs can hide backlog from other workers. Schedule `cron` jobs through the same capacity model: a nightly run that enqueues 10,000 exports is still an arrival burst.\n\n## Diagram: the backlog as a buffer\n\n![At 120 arrivals per minute and 90 completed jobs per minute, the queue grows by 30 jobs per minute.](/learning/async-systems/backpressure.svg)\n\n```aosdf-diagram\nArrivals (120/min) ──▶ Queue (+30/min) ──▶ Workers (90/min) ──▶ File store\n                          │                    │\n                          └── oldest age       └── concurrency cap\n                              reveals delay        protects dependency\n```\n\n[Explore the full queue delivery diagram](/queue-delivery-lifecycle.archify.html) to see where the worker claim sits in the delivery path.\n\n## Use the right trigger\n\nScale on a signal close to user impact, such as oldest job age relative to a completion target, while considering queue depth and worker utilization. Queue depth alone has no universal “bad” value: 600 one-second jobs and 600 ten-minute jobs are different. If the dependency is the bottleneck, more workers amplify failure. Apply backpressure at intake or worker concurrency instead.\n\n## Try it\n\nRecalculate the example for four workers and for eight workers. Assume the file store handles at most 100 jobs/minute. Decide which worker count you would allow, what admission rule you would use during a peak, and which metric would page a human.\n\n## Check your understanding\n\n- Why can a growing queue be healthy briefly but harmful over time?\n- Why might adding workers make throughput worse?\n- What does oldest job age show that queue depth does not?\n\n**Answer guide:** bursts can be buffered if they drain before deadlines; a saturated dependency can slow under more concurrency; age measures the delay experienced by work already accepted.\n\n## Read further\n\n- [Amazon SQS CloudWatch metrics](https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-available-cloudwatch-metrics.html)\n- [RabbitMQ consumer prefetch](https://www.rabbitmq.com/docs/consumer-prefetch)\n","03-retries-and-dlq.md":"# Timeouts, retries, and dead-letter queues\n\nRetries can recover from temporary failure, but they also repeat work and add load. Treat each retry as a deliberate decision based on the failure, the job's deadline, and the safety of its effect.\n\n## Classify failures before setting a policy\n\nFor an export worker, distinguish:\n\n| Failure | First response | Why |\n| --- | --- | --- |\n| File store returns a transient `503` | Retry with bounded backoff and jitter | The dependency may recover |\n| Source document no longer exists | Mark failed or skip by policy | Repeating cannot restore the input |\n| Message schema version is unsupported | Quarantine and alert | Every retry would fail the same way |\n| Worker times out after file creation | Check durable result before retrying | The effect may already exist |\n| Tenant loses permission | Stop and record a safe failure | Authorization must be checked at execution |\n\nUse **timeouts** at every network call so a stuck dependency does not occupy a worker indefinitely. Allow a little margin between the dependency timeout, the worker's overall deadline, and the broker visibility lease. A circuit breaker can temporarily stop calls to a clearly failing dependency, but a queued job still needs a later retry or explicit failure outcome.\n\n## Bound the retry budget\n\nOne policy might attempt after about 0, 2, 6, and 14 seconds, with jitter, then quarantine the job. The numbers are illustrative; derive them from the dependency's recovery behavior and the user's completion promise. Jitter spreads retries from many workers so they do not all strike a recovering service together. Avoid stacking independent SDK, worker, and broker retries without counting their combined attempts.\n\nKeep a **deadline** or maximum elapsed time as well as an attempt limit. A four-attempt policy that stretches beyond the user's useful window is not reliable delivery. Record attempt count, last error class, and next eligible time without leaking document content into logs.\n\n## Diagram: bounded failure handling\n\n![A claimed job calls a dependency; success persists a result, while repeated failure moves through retry to a dead-letter queue and reviewed replay.](/learning/async-systems/retries.svg)\n\n```aosdf-diagram\nClaim job ──▶ call file store ──▶ success ──▶ persist result ──▶ acknowledge\n                    │\n                    ├── transient ──▶ backoff + jitter ──▶ retry\n                    └── permanent / exhausted ──▶ DLQ + failed status + alert\n```\n\n[Explore the full queue delivery diagram](/queue-delivery-lifecycle.archify.html) for the retry and quarantine branch.\n\n## A dead-letter queue is a holding area\n\nA DLQ preserves messages that repeatedly fail so operators can inspect them without blocking healthy work. It is not a substitute for a user-facing failure state. For each quarantined export, correlate the message to its operation and record a safe reason. Provide a controlled replay procedure: fix the cause, inspect whether the effect already happened, choose one message or a bounded batch, replay with the same operation ID, and observe the outcome. Preserve redrive history so a poison message does not loop forever.\n\n## Try it\n\nWrite a retry table for the five failures above. Choose a dependency timeout, worker deadline, visibility lease, maximum attempts, and overall completion deadline. Explain one case in which the worker should **not** retry.\n\n## Check your understanding\n\n- Why can an immediate retry storm extend an outage?\n- Why must a timeout be treated as an uncertain outcome?\n- What must be checked before replaying a DLQ message?\n\n**Answer guide:** retries consume scarce capacity; the remote effect may have completed before the response was lost; inspect the cause and whether the operation's effect already exists.\n\n## Read further\n\n- [Amazon Builders' Library: timeouts, retries, and backoff with jitter](https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/)\n- [Amazon SQS dead-letter queues](https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-dead-letter-queues.html)\n","04-idempotency.md":"# Idempotency and delivery guarantees\n\nAn at-least-once broker may deliver the same logical job more than once. A worker can also finish its work and crash before acknowledging the message. Design the **effect** to be safe under repetition rather than equating one delivery with one action.\n\n## Name the logical effect\n\nIn the export example, `operationId` is stable across retries. Use it to name the output object, such as `exports/exp_82/result.pdf`, and to guard the status transition. The `jobId` or broker receipt may change; neither is a suitable deduplication key for the business operation.\n\nAn idempotent result write can follow this outline:\n\n```text\nclaim operation exp_82\nif status == succeeded: acknowledge existing result\nif status == cancelled: acknowledge without new effect\nacquire a bounded processing claim for exp_82\ncreate result at deterministic key or staging key\ncommit result reference and succeeded state conditionally\nacknowledge message\n```\n\nThe processing claim prevents ordinary overlap, but its lease can expire. The final result write still needs a uniqueness or conditional-update rule. If creating the file has a non-repeatable side effect, use a provider idempotency key when available and retain the provider's result ID. A local “processed” flag alone cannot atomically guarantee what an external provider did.\n\n## Diagram: the lost acknowledgement\n\n![Worker A completes an export but loses its acknowledgement; Worker B sees the existing result after redelivery and acknowledges without creating a second file.](/learning/async-systems/idempotency.svg)\n\n```aosdf-diagram\nWorker A ──▶ writes exports/exp_82/result.pdf ──▶ commits succeeded\n                                         │\n                                         └── crash before queue ack\nQueue ──▶ redelivers exp_82 ──▶ Worker B sees succeeded ──▶ ack only\n```\n\n[Explore the full queue delivery diagram](/queue-delivery-lifecycle.archify.html) and look at the gap between applying an effect and acknowledgement.\n\n## Be precise about guarantees\n\n**At-most-once** processing can lose work but avoids broker-driven repeats. **At-least-once** prioritizes retry after uncertainty and requires duplicate-safe consumers. “Exactly once” claims usually apply within a narrow subsystem or transaction boundary; they do not magically cover an external API, object store, and database together. Describe the actual observable effect: for example, “one downloadable export per operation ID, despite duplicate queue delivery.”\n\nOrdering is a separate concern. A standard queue may deliver out of order. If two jobs update the same document, use a version or sequence check so an older export request cannot overwrite a newer result. A FIFO queue can help with broker order, but it does not replace state validation.\n\n## Try it\n\nTrace two workers that receive `exp_82` concurrently. One completes while the other's claim expires. Write the unique key or conditional update that prevents two visible files, and explain what changes if the worker also charges a credit card.\n\n## Check your understanding\n\n- Why should deduplication use `operationId` instead of the delivery receipt?\n- What happens after a successful effect but lost acknowledgement?\n- Why is a local processed flag insufficient for an external payment?\n\n**Answer guide:** the operation remains the same across deliveries; the job can be redelivered; the database and external provider may disagree unless the provider offers an idempotency contract or reconciliation path.\n\n## Read further\n\n- [Amazon SQS standard queues](https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/standard-queues.html)\n- [Amazon SQS visibility timeout](https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-visibility-timeout.html)\n","05-events-and-sagas.md":"# Events, outbox, and sagas\n\nA work queue distributes tasks to workers. A published event states that something happened and may be consumed independently by several subscribers. The distinction shapes who owns success: an export command has one processing owner; an `ExportCompleted` event might inform a notification service and an audit service without making either responsible for creating the file.\n\n## Pick a communication contract\n\n| Contract | Example | Consumer relationship |\n| --- | --- | --- |\n| Command / work queue | `GenerateExport(exp_82)` | One logical task is claimed by a worker |\n| Event / pub-sub | `ExportCompleted(exp_82)` | Independent subscribers react to a fact |\n| Request / response | `GET /exports/exp_82` | Caller needs a current answer |\n\nPub/sub fan-out can produce different outcomes for each subscriber. A notification failure should not silently reverse a completed export. Each subscriber needs its own retry and deduplication policy. Include event ID, type, schema version, subject ID, time, and trace context. Version payloads so older consumers can handle or reject them deliberately.\n\n## Close the database-to-broker gap\n\nThis code is unsafe: `UPDATE exports ...; COMMIT; publish(message)`. If the process crashes after commit and before publish, the operation stays accepted but no worker sees it. Publishing first has the opposite problem: a worker may act on state that later rolls back.\n\nA **transactional outbox** stores the operation and an outbox row in one database transaction. A relay publishes pending rows and marks them sent. The relay can publish the same row twice if it crashes after publishing, so consumers still need idempotency. The outbox solves loss between one database and broker; it does not make all downstream effects atomic.\n\n## Diagram: durable event publication\n\n![The API commits state and an outbox row together; a relay publishes to a broker for a worker and other subscribers.](/learning/async-systems/outbox-events.svg)\n\n```aosdf-diagram\nAPI ──▶ DB transaction: export row + outbox row\n                              │\n                              └──▶ relay ──▶ broker ──▶ export worker\n                                              └──────▶ audit subscriber\n```\n\n[Explore the full queue delivery diagram](/queue-delivery-lifecycle.archify.html) to see where the outbox fits before publishing.\n\n## Coordinate multi-service work with a saga\n\nSuppose a paid export requires reserving a credit and then generating a file. Those steps cross service boundaries. A saga records progress and, on failure, runs a business **compensation** such as releasing an unused credit. Compensation is not a database rollback: a notification already sent or a file already downloaded may be irreversible. Define what can be compensated, what must be reconciled, and when a human must intervene.\n\nAvoid distributed transactions by default when a local transaction plus outbox and explicit compensation meets the business need. If a stronger cross-system atomic guarantee is truly required, state that requirement and evaluate the participating systems' transaction support and operational cost.\n\n## Try it\n\nDesign the export outbox row and `ExportCompleted` event. Simulate a relay crash after publish. Then add a credit reservation and write the compensation step for file generation failure. Name one effect that cannot be undone.\n\n## Check your understanding\n\n- Why can the outbox relay still publish twice?\n- Why should each event subscriber own its own deduplication rule?\n- Why is a saga compensation different from rolling back a SQL transaction?\n\n**Answer guide:** the relay can crash before recording delivery; subscribers perform different effects and fail independently; a compensation is a new business action after earlier steps may already be visible.\n\n## Read further\n\n- [Transactional outbox pattern, Chris Richardson](https://microservices.io/patterns/data/transactional-outbox)\n- [Saga pattern, Chris Richardson](https://microservices.io/patterns/data/saga.html)\n- [AWS decision guide: SQS, SNS, or EventBridge](https://docs.aws.amazon.com/decision-guides/latest/decision-guides/sns-or-sqs-or-eventbridge.html)\n","06-delivery-channels.md":"# Webhooks, live updates, and scheduled jobs\n\nOnce an export is running, different recipients need different ways to learn its state. A browser, another server, and a scheduled maintenance task do not share the same delivery contract. The queue remains the internal work path; these are ways to trigger or report work.\n\n## Choose by recipient and direction\n\n| Channel | Good fit | Important boundary |\n| --- | --- | --- |\n| Status polling | Browser checks an export every few seconds | Bound frequency, use caching, stop on terminal state |\n| Server-sent events (SSE) | Server pushes progress to a browser | One-way stream; reconnect and fetch current state |\n| WebSocket | Browser and server exchange frequent bidirectional messages | Connection lifecycle, auth renewal, and backpressure |\n| Webhook | Your server notifies another server | Sign requests, handle retries and receiver deduplication |\n| Cron / scheduled job | Periodic cleanup or reconciliation | Prevent overlap; use a durable operation ID |\n\n**Long polling** is a request held open until an update or timeout, followed by another request. It can fit environments without a persistent stream, but it still needs timeouts and connection budgets. None of these channels replaces the durable operation record. After reconnect, the client should query current state; an update can be delayed or missed.\n\n## Design a webhook as at-least-once notification\n\nFor `ExportCompleted`, create a webhook delivery record with an event ID and destination. Sign the body using a secret scoped to that endpoint, include a timestamp, enforce a replay window, and validate destination URLs to reduce server-side request forgery risk. Acknowledge a receiver's successful response; retry transient failures with a bounded schedule and show delivery status. Receivers should deduplicate on event ID and respond quickly, handing slow work to their own queue.\n\nA webhook should not expose a private download URL to a recipient who lacks access. Include a stable export ID and let the recipient retrieve details through an authorized API.\n\n## Diagram: one status, several subscribers\n\n![Browser polling reads a durable status record, while the server pushes updates through server-sent events and signed partner webhooks.](/learning/async-systems/delivery-channels.svg)\n\n```aosdf-diagram\nExport status store ──▶ GET status (polling)\n         │\n         ├──▶ SSE / WebSocket update to browser\n         └──▶ webhook delivery queue ──▶ signed POST to partner\n```\n\n[Explore the full queue delivery diagram](/queue-delivery-lifecycle.archify.html) for the durable processing path behind these notifications.\n\n## Treat schedules as producers\n\nA nightly reconciliation job should emit bounded work units, not hold one process open for hours. Give each run a unique ID and each item a stable operation key. If a run overlaps its predecessor, either skip, join, or partition explicitly. Reconciliation can compare accepted exports against completed files and repair a missed outbox publication or status update. Keep the same duplicate-safe worker rule.\n\n## Try it\n\nChoose a progress channel for a browser that only needs updates every five seconds, and another for a live collaborative editor. Design a partner webhook payload with event ID, timestamp, and signature. Describe what the browser does after losing its connection.\n\n## Check your understanding\n\n- Why does an SSE progress update not replace `GET /exports/{id}`?\n- What should a webhook receiver do with the same event ID twice?\n- Why can a cron job overload the same queue as user requests?\n\n**Answer guide:** live messages can be missed; the receiver should make the repeated event harmless; scheduled work can arrive as a large burst and consume worker capacity.\n\n## Read further\n\n- [MDN: using server-sent events](https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events)\n- [MDN: WebSocket API](https://developer.mozilla.org/en-US/docs/Web/API/WebSockets_API)\n- [GitHub webhook delivery and validation guidance](https://docs.github.com/en/webhooks/using-webhooks/best-practices-for-using-webhooks)\n","07-operations.md":"# Operating and reviewing a delivery system\n\nThe architecture is incomplete until someone can answer: **Are accepted operations finishing within the promise, and what do we do when they do not?** Broker health alone cannot answer that. Compare queue signals with the durable operation states visible to users.\n\n## Define a small service objective\n\nFor a sample export product, suppose the promise is “99% of accepted exports reach a terminal state within ten minutes.” Measure from the durable acceptance timestamp to `succeeded` or a clear `failed` state. Report successful completion separately: failing fast is observable but does not satisfy a success goal. Segment by tenant, job type, size, and dependency so one noisy group does not hide another.\n\nUseful signals include:\n\n- Oldest visible message age and queue depth: is accepted work waiting?\n- In-flight count and lease expirations: are workers stuck or timing out?\n- Attempt count, retry rate, and DLQ arrivals: is a failure repeating?\n- Operation age by state: are records stuck in `accepted` or `running`?\n- End-to-end completion latency and success rate: what does a user experience?\n- Outbox unpublished age: did durable intent stop reaching the broker?\n\nBroker counts are often approximate. Use them for operational trends and alerts; use the operation store for exact product state.\n\n## Diagram: signals lead to a recovery decision\n\n![Queue age, operation age, and dead-letter messages lead to triage, then overload controls or poison-job isolation, followed by verified recovery.](/learning/async-systems/operations.svg)\n\n```aosdf-diagram\nQueue age + operation age + DLQ count\n                 │\n                 ▼\nTriage: intake? broker? worker? dependency? result store?\n                 │\n         ├── transient outage ──▶ limit intake / restore / drain\n         └── poison job ──▶ isolate / fix / replay bounded set\n```\n\n[Explore the full queue delivery diagram](/queue-delivery-lifecycle.archify.html) while tracing a stuck operation.\n\n## Write the runbook before the incident\n\nAn operator should be able to find a job by operation ID, see its schema version and attempts, inspect a sanitized error, determine whether the effect happened, and choose **retry**, **mark failed**, **cancel**, or **replay after repair**. Limit replay to a selected set with an owner and audit record. Define who may pause producers or workers, and how to resume without releasing a second wave of retries onto a recovering dependency.\n\nTrace the request, outbox relay, broker publish, worker claim, provider call, result write, and acknowledgement with the same correlation ID. Avoid storing full document bodies or secrets in traces. Alert on user-impacting age and failure thresholds; route pages to someone who can take action.\n\n## Worked review\n\nAt 09:00, export intake rises to 120/minute while workers complete 90/minute. By 09:20, backlog is about 600 jobs. At 09:25 the file store returns `503`, and retry rate rises. Adding workers would increase pressure on the store. A safer response is to limit new intake, cap concurrent file writes, keep bounded retries with jitter, and watch oldest age and success rate. Once the store recovers, drain deliberately. Inspect DLQ messages before replay and confirm an existing result for each uncertain timeout.\n\n## Try it\n\nWrite a one-page design review containing: request/status contract, message schema, backlog calculation, failure classification, retry budget, deduplication key, outbox boundary, progress channel, three alerts, and a DLQ replay procedure. Walk through a worker crash after file creation.\n\n## Check your understanding\n\n- Why can a low queue depth coexist with broken user outcomes?\n- Why should replay require an effect check?\n- When is scaling workers the wrong incident response?\n\n**Answer guide:** messages may be consumed but operations stuck or failed; an uncertain attempt may already have applied the effect; a saturated dependency can fail harder under extra concurrency.\n\n## Read further\n\n- [Amazon SQS CloudWatch metrics](https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-available-cloudwatch-metrics.html)\n- [Amazon SQS dead-letter queues and redrive](https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-dead-letter-queues.html)\n"},"scale-design":{"README.md":"# Scale and system design\n\nA system design is a set of decisions about how requests move through software, where data lives, what happens under load, and what users see when parts fail. **Scale** means the system can keep its promised behavior as demand grows. It is not a server count: a fast API with a saturated database or an incorrect cache is not successfully scaled.\n\nThis module starts with a simple **shared document library**. A reader opens a document, an editor changes it, and authorized users search their library. We begin with one API process and one database. Each later lesson adds a component only when a stated requirement or measured bottleneck justifies it. The example uses ordinary HTTP and relational data; the principles apply to many products.\n\n![Reader and editor requests enter a service, which reads and writes the primary database and stores document bodies.](/learning/scale-design/system-map.svg)\n\n```aosdf-diagram\nReader / Editor ──▶ API ──▶ Primary database (metadata, access, versions)\n                       └────▶ Object store (document bodies)\n```\n\n## Who this is for\n\nBegin with HTTP requests and a database table; no distributed-systems background is assumed. If you already review production architectures, use the worked estimates, failure contracts, and review checklist to challenge your assumptions. Every lesson has a browser-rendered figure, a text alternative, an exercise, and primary references.\n\n## What you will learn\n\n- Turn user promises into measurable latency, correctness, capacity, and recovery requirements.\n- Estimate peak load, concurrency, and p99 latency instead of sizing from average traffic alone.\n- Place load balancing, gateways, caches, replicas, partitions, and indexes at the right boundary.\n- Explain exactly what a user may observe during replication lag, simultaneous edits, and network partitions.\n- Make API, schema, and operational changes while old and new versions coexist.\n\n## Learning approach\n\nRead in order if these topics are new. After each **Engineering exercise**, add a paragraph to one design note for the document library: requirements, capacity estimate, traffic path, cache policy, data access, consistency contract, concurrency rule, and rollout plan. Numbers are illustrative, not universal defaults. A professional design replaces them with measurements and an explicit error budget.\n\n## Diagram: the architecture as demand grows\n\nThe full diagram shows an edge cache, load balancer, API fleet, application cache, primary database, read replica, and object store. Follow its arrows while reading. It is a possible design, not a mandate to deploy every box.\n\n\x3c!-- SCALE_DESIGN_DIAGRAM --\x3e\n\n## Reference stack at a glance\n\nThese are examples of products and frameworks an engineering team could use to implement the paths in this module. Each lesson explains a choice and its limits; the logos identify actual tools, not a required stack. The browser serves these marks from local SVG assets.\n\n| Logo | Tool | Concrete role |\n| :---: | --- | --- |\n| ![NGINX logo](/learning/scale-design/logo-nginx.svg) | [NGINX](https://nginx.org/en/docs/) | Reverse proxy and load balancing at the API entry point |\n| ![FastAPI logo](/learning/scale-design/logo-fastapi.svg) | [FastAPI](https://fastapi.tiangolo.com/) | Example Python HTTP framework for the document API |\n| ![Kubernetes logo](/learning/scale-design/logo-kubernetes.svg) | [Kubernetes](https://kubernetes.io/docs/concepts/) | Service discovery, readiness, and workload autoscaling |\n| ![PostgreSQL logo](/learning/scale-design/logo-postgresql.svg) | [PostgreSQL](https://www.postgresql.org/docs/current/) | Authoritative metadata, transactions, indexes, and replication |\n| ![Redis logo](/learning/scale-design/logo-redis.svg) | [Redis](https://redis.io/docs/latest/) | Bounded application cache and shared rate-limit state |\n| ![Cloudflare logo](/learning/scale-design/logo-cloudflare.svg) | [Cloudflare Cache](https://developers.cloudflare.com/cache/) | Edge delivery of public, cacheable assets |\n| ![OpenTelemetry logo](/learning/scale-design/logo-opentelemetry.svg) | [OpenTelemetry](https://opentelemetry.io/docs/) | Traces across request, data, and storage paths |\n| ![Prometheus logo](/learning/scale-design/logo-prometheus.svg) | [Prometheus](https://prometheus.io/docs/) | Request histograms, saturation, and error measurements |\n| ![Grafana k6 logo](/learning/scale-design/logo-k6.svg) | [Grafana k6](https://grafana.com/docs/k6/latest/) | Representative load tests before capacity decisions |\n\n## Lesson index\n\n| Order | Lesson | Question it answers |\n| --- | --- | --- |\n| 1 | [What system design solves](/learn/ai-engineer-fde/scale-design/system-design-basics) | What must a service do before adding servers? |\n| 2 | [Capacity, throughput, and tail latency](/learn/ai-engineer-fde/scale-design/capacity-and-latency) | How much traffic and delay must the design absorb? |\n| 3 | [Scaling and load balancing](/learn/ai-engineer-fde/scale-design/scaling-and-balancing) | How do extra instances help without creating a new bottleneck? |\n| 4 | [The edge and API boundary](/learn/ai-engineer-fde/scale-design/edge-and-api-boundary) | Where are requests routed, limited, and authenticated? |\n| 5 | [Caching and invalidation](/learn/ai-engineer-fde/scale-design/caching-and-invalidation) | What can be reused, and how does it become fresh? |\n| 6 | [Queries, indexes, and connections](/learn/ai-engineer-fde/scale-design/queries-and-connections) | How can data access stay fast without exhausting the database? |\n| 7 | [Replication, partitioning, and sharding](/learn/ai-engineer-fde/scale-design/replication-and-sharding) | When does one database stop being enough? |\n| 8 | [Consistency, partitions, and time](/learn/ai-engineer-fde/scale-design/consistency-and-time) | What does a reader see after a write or network failure? |\n| 9 | [Concurrency, locks, and runtime health](/learn/ai-engineer-fde/scale-design/concurrency-and-runtime) | How are simultaneous edits and process failures controlled? |\n| 10 | [Compatible change and architecture review](/learn/ai-engineer-fde/scale-design/compatibility-and-review) | How can a design evolve without breaking current users? |\n\n## Completion check\n\nDraw the read and edit paths. Explain the p99 target, peak load, database connection limit, cache freshness rule, read-after-write promise, simultaneous edit rule, and one rollback path. For each added component, say which measured problem it solves and which new failure it introduces.\n\n## Primary references\n\n- [Google SRE: service level objectives](https://sre.google/sre-book/service-level-objectives/)\n- [Google SRE: monitoring distributed systems](https://sre.google/sre-book/monitoring-distributed-systems/)\n- [PostgreSQL: using EXPLAIN](https://www.postgresql.org/docs/current/using-explain.html)\n","00-system-design-basics.md":"# What system design solves\n\nA system is the people-facing behavior plus the software and data paths that produce it. **System design** asks how those parts will meet a promise under ordinary traffic, failure, and change. A diagram is useful only when its arrows have a contract: who sends what, where truth is stored, and what happens if a box is unavailable.\n\n## Begin with behavior, not boxes\n\nOur document library has three actions: open a document, save an edit, and search documents the user may access. Begin with one API and one relational database. Store a document ID, owner, access rule, title, version, and object-storage key in the database; keep larger document bodies in object storage. On a read, authorize the user **before** returning a body or a cached result. On a save, update the document version atomically and return the new version.\n\nWrite two kinds of requirement. **Functional**: an editor can save a document and another authorized reader can open it. **Quality**: for example, 99% of authorized document opens finish within 400 ms, and a successful save is visible to that editor immediately. Define what a failed save looks like; a timeout does not prove that no write occurred. A service level objective (SLO) measures an observable promise, whereas a server specification is only one means to meet it.\n\n| Concern | Example question | Initial answer |\n| --- | --- | --- |\n| Users | Who can read and edit? | Owner and granted collaborators |\n| Correctness | Can edits overwrite each other? | Compare the submitted version |\n| Speed | Which action matters most? | Document open p99 under 400 ms |\n| Durability | What must survive a crash? | A confirmed edit and its version |\n| Failure | Can a read be stale? | Listing may lag; own edit may not |\n\n## Diagram: one request before scale\n\n![An authorized reader passes through the API; metadata and access are checked before the document body is returned.](/learning/scale-design/requirements.svg)\n\n```aosdf-diagram\nBrowser ──▶ API ──▶ access + metadata in primary DB\n                └──▶ body in object storage ──▶ authorized response\n```\n\nThe drawing intentionally omits caches and replicas. Starting here exposes the correctness boundary that every later optimization must preserve. A cache key that ignores user permissions could turn a fast design into a data leak.\n\n## Worked design decision\n\nSuppose opening a small document takes 130 ms at p99 and the goal is 400 ms. No scaling component is justified yet. Suppose instead search takes 1.8 seconds because it scans every document. Adding API replicas will not change the scan; inspect the query and index first. This is the core system-design habit: find the limiting path, then change that path.\n\n## Implementation: a credible first stack\n\nAn engineer should be able to build and instrument the smallest version before sketching a fleet. One possible stack is NGINX at ingress, FastAPI for a Python document API, PostgreSQL for metadata and versions, an S3-compatible object store for bodies, and OpenTelemetry for request traces. The API still owns authorization; storage location does not decide who can see a document.\n\n| Logo | Technology and documentation | Role in this design | Check before adopting |\n| :---: | --- | --- | --- |\n| ![nginx logo](/learning/scale-design/logo-nginx.svg) | [NGINX](https://nginx.org/en/docs/http/ngx_http_proxy_module.html) | Forward HTTP requests to the API. | Set timeouts and trusted forwarded headers explicitly. |\n| ![fastapi logo](/learning/scale-design/logo-fastapi.svg) | [FastAPI](https://fastapi.tiangolo.com/tutorial/dependencies/) | Express request handlers and inject an authenticated principal. | Put object authorization in the handler or service, not only a global dependency. |\n| ![postgresql logo](/learning/scale-design/logo-postgresql.svg) | [PostgreSQL](https://www.postgresql.org/docs/current/) | Keep access, metadata, and version changes in transactions. | Model permission and version constraints before optimizing. |\n| ![opentelemetry logo](/learning/scale-design/logo-opentelemetry.svg) | [OpenTelemetry](https://opentelemetry.io/docs/concepts/) | Trace the request across API, database, and object retrieval. | Do not put document content or tokens in spans. |\n\nFor the first implementation, define `documents(id, tenant_id, owner_id, version, object_key)` and a FastAPI `GET /documents/{id}` handler. A dependency can resolve the signed-in principal; the handler or document service must then check that principal's tenant and document permission **before** fetching the object. Record one span for the permission query and one for object retrieval. A fast response that bypasses the permission check is a correctness failure, regardless of its latency.\n\n## Engineering exercise\n\nWrite four sentences for a photo library: one user action, one correctness rule, one p99 target, and one failure response. Sketch the smallest request path and mark the durable source of truth.\n\n## Design review questions\n\n- What is the difference between “four servers” and “p99 open latency under 400 ms”?\n- Why must an access check apply even when a body is cached?\n- Which measurement would justify an index before a load balancer?\n\n**Review criteria:** the first is an implementation choice and the second is a user-visible promise; cached data can still be private; a slow query plan or high database scan time points at the data path.\n\n## Read further\n\n- [Google SRE: service level objectives](https://sre.google/sre-book/service-level-objectives/)\n- [Google SRE: monitoring distributed systems](https://sre.google/sre-book/monitoring-distributed-systems/)\n","01-capacity-and-latency.md":'# Capacity, throughput, and tail latency\n\n**Throughput** is work completed per unit time; **latency** is elapsed time for one request. More throughput does not imply a good user experience if the slowest requests become much slower. A capacity estimate is an initial model to test, not a procurement order.\n\n## Calculate from demand to peak\n\nSuppose the library receives **10 million document opens/day** and **100,000 edits/day**. Average opens are `10,000,000 / 86,400 ≈ 116 requests/second`. If the busiest period is ten times the average, plan an initial **1,160 open requests/second**, plus edits and search. State the multiplier as an assumption and verify it from traffic telemetry. A 2\xd7 seasonal event or retry storm may require a separate scenario.\n\nIf one open occupies an API worker for 120 ms, Little\'s law gives roughly `1,160 \xd7 0.120 ≈ 139` concurrent in-flight opens at that peak. This is a first concurrency estimate; queues, I/O wait, connection pools, and burst shape still matter. If each open causes three database queries, the database sees roughly 3,480 queries/second before cache hits. Measure the real fanout.\n\n## Know what p99 measures\n\nA p99 of 400 ms means 99% of requests in the measured population finish at or below 400 ms; 1% take longer. With 10 million opens/day, that remaining 1% is still about 100,000 slow opens. Segment by endpoint, region, tenant, payload size, and result; one aggregate percentile can hide a painful subgroup. Percentiles of stages cannot simply be added to obtain end-to-end p99 because the slow requests may differ across stages.\n\nSet a rough budget: edge and network 70 ms, API work 60 ms, database 120 ms, object retrieval 100 ms, headroom 50 ms. The pieces add to 400 ms as a planning envelope, not a guarantee. Verify with end-to-end traces under representative load, especially when concurrent requests compete for connections.\n\n## Diagram: load, concurrency, and tail\n\n![Average demand rises tenfold at peak, increasing concurrent requests and making the p99 tail visible.](/learning/scale-design/capacity.svg)\n\n```aosdf-diagram\n10M opens/day \xf7 86,400 ≈ 116 average RPS\nPeak assumption \xd710 ≈ 1,160 RPS\nIn-flight estimate = 1,160 RPS \xd7 0.12 s ≈ 139\n```\n\n## Implementation: test the estimate against measured traffic\n\nUse a load generator to replay the actual read/edit/search mix, a metrics system to collect latency buckets and saturation, and a dashboard to compare the result with the target. These are complementary roles; a dashboard does not produce load and a load test does not replace production telemetry.\n\n| Logo | Technology and documentation | Role in this design | Check before adopting |\n| :---: | --- | --- | --- |\n| ![k6 logo](/learning/scale-design/logo-k6.svg) | [Grafana k6](https://grafana.com/docs/k6/latest/get-started/) | Generate a staged peak load with realistic requests. | Use seeded data and a representative endpoint mix. |\n| ![prometheus logo](/learning/scale-design/logo-prometheus.svg) | [Prometheus histograms](https://prometheus.io/docs/practices/histograms/) | Collect request duration buckets, RPS, errors, and pool wait. | Choose buckets around the SLO; avoid raw document IDs as labels. |\n| ![grafana logo](/learning/scale-design/logo-grafana.svg) | [Grafana](https://grafana.com/docs/grafana/latest/datasources/prometheus/query-editor/) | Plot p99, traffic, errors, and dependency saturation together. | Separate route and tenant cohorts without exploding cardinality. |\n\nA starting k6 scenario ramps to the estimated 1,160 opens/second while mixing edits and search. Report both **offered** and **completed** RPS: a system that drops requests can appear fast if only successful responses are timed. For a classic Prometheus histogram named `http_request_duration_seconds`, a sample p99 query is:\n\n```promql\nhistogram_quantile(0.99, sum by (le) (rate(http_request_duration_seconds_bucket{route="document_open"}[5m])))\n```\n\nThe metric name and `route` label are examples; instrument your actual API and bound label cardinality. Compare the p99 with connection-pool wait and database time to find the stage that causes the tail.\n\n## Engineering exercise\n\nEstimate average and 8\xd7 peak RPS for 2.4 million events/day. If service time is 250 ms, estimate in-flight requests. Then write one reason the estimate may be wrong and one metric that would correct it.\n\n## Design review questions\n\n- Why is average RPS insufficient for capacity planning?\n- Can two stages each have p99 of 100 ms and guarantee end-to-end p99 of 200 ms?\n- Why should a professional segment latency by tenant or endpoint?\n\n**Review criteria:** peaks and bursts consume capacity; percentile sets do not necessarily contain the same requests; aggregates can hide a slow or overloaded cohort.\n\n## Read further\n\n- [Google SRE: service level objectives](https://sre.google/sre-book/service-level-objectives/)\n- [Google SRE: monitoring distributed systems](https://sre.google/sre-book/monitoring-distributed-systems/)\n',"02-scaling-and-balancing.md":"# Scaling and load balancing\n\n**Vertical scaling** gives one machine more CPU, memory, or I/O capacity. **Horizontal scaling** adds machines or processes. Either may help, but only at the current bottleneck. Two API instances do not double throughput when both wait on the same saturated database.\n\n## Make API instances interchangeable\n\nA load balancer distributes incoming connections among healthy API instances. The API should keep durable state in the database or object store, not solely in one process's memory. Store browser session state in a signed token or shared session store according to the security model; do not require “sticky” routing just to find an editor's document. Health checks remove an instance that cannot serve traffic, while **draining** lets existing requests finish before a rollout or scale-down. A health check should reflect the dependencies needed for the endpoint, without causing every transient dependency blip to restart every instance.\n\nAutoscaling adds or removes instances based on a signal such as CPU, request rate, or queue depth. The signal must relate to the bottleneck, and the policy needs warm-up, bounds, and cooldown. Scaling from two to twenty API instances can accidentally create hundreds of new database connections; the connection budget is a separate design decision.\n\n## Worked bottleneck comparison\n\nAt peak, an API fleet has CPU at 85%, database CPU at 30%, and p99 latency rises with API request queueing. More API instances may help. In another peak, API CPU is 25% and database connections are maxed out. More API instances may worsen contention. Measure per-stage latency, saturation, error rate, and p99 while changing one variable. Run a load test using a realistic mix of opens, edits, and searches rather than one cheap endpoint.\n\n## Diagram: add instances at the bottleneck\n\n![A load balancer routes readers across healthy API instances; all instances share a database, whose connection limit remains a shared constraint.](/learning/scale-design/scaling.svg)\n\n```aosdf-diagram\nReaders ──▶ load balancer ──▶ API A ─┐\n                          └──▶ API B ─┼──▶ shared database\n                          └──▶ API C ─┘\n```\n\n## Implementation: route to interchangeable instances\n\nNGINX can distribute HTTP traffic; Kubernetes can manage replicas, readiness, and horizontal autoscaling; Prometheus can expose the saturation that tells you whether scaling helped. A managed load balancer can play the ingress role in another environment. None of these tools removes the shared database limit.\n\n| Logo | Technology and documentation | Role in this design | Check before adopting |\n| :---: | --- | --- | --- |\n| ![nginx logo](/learning/scale-design/logo-nginx.svg) | [NGINX load balancing](https://nginx.org/en/docs/http/load_balancing.html) | Route requests across API instances. | Configure upstream failure behavior and request timeouts. |\n| ![kubernetes logo](/learning/scale-design/logo-kubernetes.svg) | [Kubernetes HPA](https://kubernetes.io/docs/concepts/workloads/autoscaling/) | Adjust replica count from a measured workload signal. | Provide resource requests, readiness, and scale-down behavior. |\n| ![prometheus logo](/learning/scale-design/logo-prometheus.svg) | [Prometheus](https://prometheus.io/docs/introduction/overview/) | Track API saturation, database connections, and errors. | Confirm the bottleneck moved after scaling. |\n\nA small NGINX upstream for two interchangeable instances looks like this; production deployments also need TLS, readiness, and graceful draining:\n\n```nginx\nupstream document_api {\n    server api-a:8080;\n    server api-b:8080;\n}\nserver {\n    listen 80;\n    location / { proxy_pass http://document_api; }\n}\n```\n\nSet an aggregate database connection budget before raising the HPA maximum. For example, 20 replicas \xd7 12 connections = 240 potential API connections. If the database can safely support only 200 after reserves, the autoscaling policy and pool settings disagree.\n\n## Engineering exercise\n\nYour API p99 doubled after adding instances, while database active connections hit its limit. Describe what to measure next and two safer fixes. Include how you would verify the change and roll it back.\n\n## Design review questions\n\n- What makes a process stateless enough for a load balancer?\n- Why can autoscaling increase errors?\n- What is the role of draining during a deployment?\n\n**Review criteria:** any instance can reconstruct required request state from shared durable sources; new instances can overwhelm a shared dependency; draining protects in-flight work while routing stops.\n\n## Read further\n\n- [Kubernetes workload autoscaling](https://kubernetes.io/docs/concepts/workloads/autoscaling/)\n- [AWS Auto Scaling with a load balancer](https://docs.aws.amazon.com/autoscaling/ec2/userguide/autoscaling-load-balancer.html)\n","03-edge-and-api-boundary.md":"# The edge and API boundary\n\nA **reverse proxy** receives a client request and forwards it to an internal service. A **load balancer** spreads traffic among instances. An **API gateway** can add routing, authentication integration, quotas, and policy at a shared entry point. These roles may be implemented by one product, but the responsibilities should stay explicit in the design.\n\n## Trace one request through the boundary\n\nA reader requests `GET /documents/42`. At the edge, terminate TLS and reject malformed or oversized requests. The gateway routes to the document API, checks a validated identity where appropriate, and applies a per-user or per-tenant rate limit. The API still performs document-level authorization: a gateway can know the user but usually cannot know whether that user may read document 42. Internal **service discovery** maps a service name to currently healthy endpoints, so adding an instance does not require clients to learn its address.\n\nA token bucket is one rate-limit model: tokens arrive at a configured rate up to a burst capacity; each request consumes one. A full bucket allows a short burst, while a sustained flood is limited. For example, a 20-token bucket refilled at 5 tokens/second allows a burst of 20 and then roughly 5/second. Limits should be scoped to the actual abuse and fairness boundary. A single global quota can let one tenant crowd out another. Return an intelligible `429` and retry guidance when a client is limited.\n\n## Keep trust boundaries visible\n\nForwarded headers such as client IP or user identity are trustworthy only when set and sanitized by a proxy you control. The API must validate auth and authorization at its own boundary; rate limiting is not a substitute. If the gateway is unavailable, it is an availability dependency. Define timeouts, health checks, and a policy for overload before moving all traffic through it.\n\n## Diagram: edge to authorized data\n\n![TLS termination and request limits precede routing; the document API checks the user's permission before reading the record.](/learning/scale-design/api-boundary.svg)\n\n```aosdf-diagram\nBrowser ──▶ edge/proxy ──▶ gateway: route + quota ──▶ API: document authorization\n                                                    └──▶ data only after approval\n```\n\n## Implementation: make routing and limits enforceable\n\nA typical deployment uses an edge proxy, Kubernetes Service discovery, and a shared Redis-backed limiter. Envoy Gateway is another entry-point implementation when route policy and per-tenant limits need central management. Pick one owner for each rule so the API and gateway do not silently disagree.\n\n| Logo | Technology and documentation | Role in this design | Check before adopting |\n| :---: | --- | --- | --- |\n| ![envoyproxy logo](/learning/scale-design/logo-envoyproxy.svg) | [Envoy Gateway](https://gateway.envoyproxy.io/docs/concepts/rate-limiting/) | Apply local or global HTTP rate-limit policy. | Local limits are per instance; global limits need a shared service. |\n| ![kubernetes logo](/learning/scale-design/logo-kubernetes.svg) | [Kubernetes Service](https://kubernetes.io/docs/concepts/services-networking/service/) | Resolve a stable service name to healthy API endpoints. | Readiness and endpoint updates affect where requests go. |\n| ![redis logo](/learning/scale-design/logo-redis.svg) | [Redis rate limiter](https://redis.io/docs/latest/develop/use-cases/rate-limiter/) | Maintain quota state shared across gateway instances. | Make read-decide-update atomic; define outage behavior. |\n\nFor a tenant quota, key the limit by `tenant_id` and route, not a client-provided IP alone. A token bucket with capacity 20 and refill 5/second permits a short burst while holding the sustained rate near 5/second. If the decision uses Redis, perform the token calculation and update atomically, for example through a script or a supported limiter. Decide whether an unavailable limiter fails open or closed for each endpoint; editing and public search may warrant different choices. The API still checks object authorization after the gateway accepts the request.\n\n## Engineering exercise\n\nDesign quotas for a library with one free user who may issue 10 searches/minute and a business tenant allowed 1,000/minute. Decide the token-bucket key, burst size, and response when a limit is hit. Say where document authorization happens.\n\n## Design review questions\n\n- Can a gateway's authentication check replace document authorization?\n- What does service discovery change when an API instance is replaced?\n- Why distinguish a short burst from sustained request rate?\n\n**Review criteria:** identity does not imply permission on a particular resource; discovery resolves a service name to the healthy instance set; bursts are normal but continuous excess can exhaust capacity.\n\n## Read further\n\n- [AWS API Gateway throttling and token buckets](https://docs.aws.amazon.com/apigateway/latest/developerguide/http-api-throttling.html)\n- [Kubernetes Services and service discovery](https://kubernetes.io/docs/concepts/services-networking/service/)\n","04-caching-and-invalidation.md":"# Caching and invalidation\n\nA **cache** keeps a reusable copy near the next reader. It reduces latency and work on an origin, but introduces a freshness contract. “Use a cache” is incomplete until the key, owner, lifetime, invalidation trigger, and behavior after a miss are defined.\n\n## Choose the right layer\n\nA CDN or edge cache is a good fit for public, immutable images and versioned JavaScript. Private document bodies require careful permission handling and usually should not be stored in a shared public cache. Browser caches can revalidate with `ETag` and `If-None-Match`; an unchanged representation can return `304 Not Modified`. An application cache might hold document metadata or a search result, keyed by tenant, viewer permissions, query, and data version. The key must encode all inputs that affect the result.\n\nFor document 42, a safe simple policy is: on a successful edit, increment `version` in the primary transaction; cache the body under `document:42:v7` instead of overwriting `document:42`. The response for version 8 uses a new key, so old cached bytes cannot masquerade as the new version. Old keys expire. A listing may tolerate a short TTL; the editor's immediate post-save read should use the primary or a session-aware path.\n\nIf many misses for the same popular key arrive together, all may hit the database: a **cache stampede**. Bound concurrent fills per key, use short stale-while-revalidate only where stale data is acceptable, and size the origin for a realistic miss storm. A 95% hit ratio at 1,160 RPS still sends about 58 requests/second to the origin; the number can jump to 1,160 when the cache is cold.\n\n## Diagram: hit, miss, and version change\n\n![A cache hit serves a versioned document; a miss reads the origin, and an edit creates a new versioned cache key.](/learning/scale-design/caching.svg)\n\n```aosdf-diagram\nGET doc v7 ──▶ cache v7 ── hit ──▶ response\n                   └── miss ──▶ primary + object store ──▶ fill\nEDIT doc ──▶ commit v8 ──▶ future reads use cache v8\n```\n\n## Implementation: put each cache at a deliberate boundary\n\nCloudflare Cache can keep public versioned assets at the edge. Redis can hold bounded application cache entries. NGINX can honor or generate HTTP cache headers at a controlled proxy boundary. The important engineering decision is the **cacheability rule**, not which logo sits on the architecture diagram.\n\n| Logo | Technology and documentation | Role in this design | Check before adopting |\n| :---: | --- | --- | --- |\n| ![cloudflare logo](/learning/scale-design/logo-cloudflare.svg) | [Cloudflare Cache](https://developers.cloudflare.com/cache/get-started/) | Serve public immutable thumbnails and assets near readers. | Bypass shared caching for private document responses. |\n| ![redis logo](/learning/scale-design/logo-redis.svg) | [Redis](https://redis.io/docs/latest/develop/use-cases/cache-aside/) | Store short-lived metadata or versioned derived results. | Include tenant, permission scope, and version in keys. |\n| ![nginx logo](/learning/scale-design/logo-nginx.svg) | [NGINX proxy cache](https://nginx.org/en/docs/http/ngx_http_proxy_module.html) | Control a proxy cache in self-hosted deployments. | Audit headers, cookie handling, and invalidation. |\n\nFor a fingerprinted public asset, an origin might send `Cache-Control: public, max-age=31536000, immutable`. For a private document body, use `Cache-Control: private, no-store` unless you have a reviewed private-cache contract. A Redis key like `doc:{tenant}:{id}:v{version}` avoids returning v7 as v8; permission-scoped results also need the viewer's authorization scope. Test permission revocation and cache outage explicitly before calling the path complete.\n\n## Engineering exercise\n\nDefine cache keys and freshness for public thumbnails, a private document body, and a search result. For each, say what happens after permission revocation and during a cache outage.\n\n## Design review questions\n\n- Why can a high cache hit rate hide an origin capacity problem?\n- What does an ETag help a browser avoid?\n- Why is a URL alone an unsafe key for a permission-dependent result?\n\n**Review criteria:** cold starts and stampedes send traffic to origin; revalidation can avoid retransmitting unchanged content; different viewers may be allowed to see different data.\n\n## Read further\n\n- [MDN: HTTP caching](https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching)\n- [MDN: ETag](https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/ETag)\n- [Cloudflare: cache invalidation](https://developers.cloudflare.com/cache/guides/invalidate-cache/)\n","05-queries-and-connections.md":"# Queries, indexes, and connections\n\nA database can be the limiting resource long before the API reaches CPU capacity. Faster queries, fewer round trips, and a bounded connection budget usually come before moving data to another database.\n\n## Follow the query plan\n\nSuppose the library lists documents for one tenant, newest first. This query needs to filter and order efficiently:\n\n```sql\nSELECT id, title, updated_at\nFROM documents\nWHERE tenant_id = $1 AND deleted_at IS NULL\nORDER BY updated_at DESC\nLIMIT 30;\n```\n\nA possible PostgreSQL index is `CREATE INDEX ... ON documents (tenant_id, updated_at DESC) WHERE deleted_at IS NULL`. Check `EXPLAIN (ANALYZE, BUFFERS)` against realistic data before assuming the index helps. It costs storage and write time, and a planner may choose a scan for a tiny table or broad filter. Query shape, selectivity, sort order, and pagination all matter. For deep pages, keyset pagination using `(updated_at, id)` avoids the cost and unstable results of large offsets.\n\nAn **N+1 query** appears when one list query returns 30 documents and application code makes one author or permission query for each row: 31 round trips. Fetch related data in a join or bounded batch, while retaining access filters. Instrument query count per request so the regression is visible.\n\n## Budget connections, not only CPUs\n\nEach database connection consumes server resources. If 20 API instances each allow 30 active connections, the fleet can open 600 connections before workers, migrations, and operators. A pool reuses connections and queues callers when all are busy. Set a per-instance pool cap from the database's safe total, reserve headroom for maintenance, and watch pool wait time. A larger pool can reduce waiting at the API while increasing database contention and p99 latency. Long transactions hold connections and locks; make them short.\n\n## Diagram: a bounded data path\n\n![A batched list query uses an index and a bounded connection pool; an N plus one path fans out into many unnecessary database calls.](/learning/scale-design/queries.svg)\n\n```aosdf-diagram\nAPI list request ──▶ connection pool ──▶ indexed list query ──▶ 30 rows\n                                    bad path: 1 list + 30 related queries\n```\n\n## Implementation: inspect the database before enlarging it\n\nPostgreSQL provides indexes, `EXPLAIN`, and transaction diagnostics. SQLAlchemy is one Python ORM that can batch related rows with `selectinload()` instead of issuing one lazy query per document. PgBouncer can bound physical server connections when many API processes use short transactions. OpenTelemetry traces and Grafana dashboards help distinguish time spent waiting for a pool slot from time spent executing SQL.\n\n| Logo | Technology and documentation | Role in this design | Check before adopting |\n| :---: | --- | --- | --- |\n| ![postgresql logo](/learning/scale-design/logo-postgresql.svg) | [PostgreSQL EXPLAIN](https://www.postgresql.org/docs/current/using-explain.html) | Compare scan and sort plans on production-like data. | Measure buffers and execution, not just estimated cost. |\n| ![sqlalchemy logo](/learning/scale-design/logo-sqlalchemy.svg) | [SQLAlchemy](https://docs.sqlalchemy.org/en/20/orm/queryguide/relationships.html) | Use `selectinload()` or a suitable join to avoid N+1 relationship queries. | Count generated SQL and check row multiplication on joins. |\n| ![opentelemetry logo](/learning/scale-design/logo-opentelemetry.svg) | [OpenTelemetry](https://opentelemetry.io/docs/concepts/) | Separate pool wait, query, and serialization spans. | Sanitize SQL parameters and document identifiers. |\n| ![grafana logo](/learning/scale-design/logo-grafana.svg) | [Grafana](https://grafana.com/docs/grafana/latest/) | Compare p99, active connections, and pool wait. | Set alerts on user impact, not only server CPU. |\n\nFor a Python service using SQLAlchemy, `select(Document).options(selectinload(Document.owner))` loads related owners in a bounded follow-up query rather than one query per document. The `Document` mapping must define that relationship. Record the actual SQL count for a page of 30 rows and compare both strategies; eager loading a large collection can move the bottleneck to memory or network transfer.\n\nFor the list query above, a candidate PostgreSQL index is:\n\n```sql\nCREATE INDEX CONCURRENTLY documents_tenant_recent_idx\nON documents (tenant_id, updated_at DESC)\nWHERE deleted_at IS NULL;\n```\n\nRun `EXPLAIN (ANALYZE, BUFFERS)` before and after on representative data. `CONCURRENTLY` reduces blocking of writes but takes longer and has operational constraints. If using [PgBouncer](https://www.pgbouncer.org/config), choose `pool_mode` deliberately: transaction pooling can break features that expect session state. Track **server** connections as well as client connections; a pool is not unlimited database capacity.\n\n## Engineering exercise\n\nGiven 16 API instances and a database budget of 240 application connections, reserve 48 for workers and admin tasks. Set an initial maximum API pool per instance and show the arithmetic. Then explain how you would detect a slow query versus pool exhaustion.\n\n## Design review questions\n\n- Does adding an index always speed up every query?\n- Why can a connection pool be full when CPU is low?\n- What is the N+1 cost for a page of 30 rows?\n\n**Review criteria:** indexes have maintenance cost and fit specific filters and sorts; slow I/O or long transactions can occupy connections; one initial query plus 30 related queries creates 31 round trips.\n\n## Read further\n\n- [PostgreSQL: using EXPLAIN](https://www.postgresql.org/docs/current/using-explain.html)\n- [PostgreSQL: CREATE INDEX](https://www.postgresql.org/docs/current/sql-createindex.html)\n- [PostgreSQL: resource consumption and connections](https://www.postgresql.org/docs/current/runtime-config-resource.html)\n","06-replication-and-sharding.md":"# Replication, partitioning, and sharding\n\nA **replica** copies changes from a primary database, often to serve reads or aid recovery. A **partition** divides one logical table into pieces. **Sharding** distributes data across independent database servers. They solve different constraints and introduce different failure modes.\n\n## Add a replica only with a staleness contract\n\nSuppose the document listing is read-heavy. A read replica may absorb listing queries, but asynchronous replication can lag. An editor saves version 8 to the primary and immediately reads a replica still at version 7. That is not merely a performance issue; the UI may claim the save failed. Route the editor's immediate read to the primary, track a session version, or wait until the replica has caught up. Define how much staleness a general reader may see. Monitor replay lag and failover behavior, not just replica CPU. A replica does not remove write pressure from the primary.\n\n## Split data deliberately\n\nPostgreSQL table partitioning may help a very large `document_events` table when queries and retention align with a partition key such as month. It is still one logical database system. Sharding might place tenants on different database clusters when one primary cannot handle total write/storage load. Choose a stable routing key, keep operations that need one transaction together, and plan cross-shard searches and migrations. A large tenant can become a **hot shard** even when average shard load is low; detect skew and plan for tenant moves or finer subdivision.\n\n| Technique | Helps with | New cost |\n| --- | --- | --- |\n| Read replica | Read capacity, recovery options | Lag and failover complexity |\n| Table partitioning | Large-table maintenance and pruning | Partition key and query discipline |\n| Sharding | Write/storage limits of one cluster | Routing, rebalance, cross-shard work |\n\n## Diagram: copies versus splits\n\n![A primary asynchronously feeds a read replica, while two shards hold different tenant groups rather than full copies.](/learning/scale-design/replication.svg)\n\n```aosdf-diagram\nPRIMARY ──async copy──▶ REPLICA (same logical data, potentially stale)\nSHARD A: tenants 1–50    SHARD B: tenants 51–100 (different data)\n```\n\n## Implementation: distinguish native replication from distribution\n\nPostgreSQL streaming replication supplies an asynchronous read copy. Native table partitioning divides a table inside a PostgreSQL deployment. Citus is a PostgreSQL extension for distributed tables; it is a possible sharding path when tenant-local queries dominate. Start from the actual write, storage, and read bottleneck before introducing one of these.\n\n| Logo | Technology and documentation | Role in this design | Check before adopting |\n| :---: | --- | --- | --- |\n| ![postgresql logo](/learning/scale-design/logo-postgresql.svg) | [PostgreSQL replication](https://www.postgresql.org/docs/current/warm-standby.html) | Serve tolerated-stale reads or prepare a failover path. | Measure replay lag and read-after-write behavior. |\n| ![postgresql logo](/learning/scale-design/logo-postgresql.svg) | [PostgreSQL partitioning](https://www.postgresql.org/docs/current/ddl-partitioning.html) | Prune old event-table partitions by time. | Queries must filter on the partition key to benefit. |\n| ![prometheus logo](/learning/scale-design/logo-prometheus.svg) | [Prometheus](https://prometheus.io/docs/introduction/overview/) | Alert on lag, primary write pressure, and hot tenants. | Compare distributions per shard; averages hide skew. |\n\nA Citus-style tenant-sharded table uses `tenant_id` as the distribution key so a document and its access rows can be colocated; see the [Citus data-modeling guidance](https://github.com/citusdata/citus_docs/blob/master/sharding/data_modeling.rst). That requires changing keys, joins, and migration paths. It is not a transparent speed switch. Before a replica rollout, test `save v8 → immediate read`; before sharding, test a cross-tenant admin query and movement of a hot tenant.\n\n## Engineering exercise\n\nA user saves a document, then opens the listing and sees the old title. Draw the write and read paths that caused this. Choose one fix and state the cost. Then decide whether a 500-million-row event table needs partitioning, sharding, both, or more evidence.\n\n## Design review questions\n\n- Can a read replica make the primary's writes faster by itself?\n- What is a hot shard?\n- Why is sharding harder for a query across all tenants?\n\n**Review criteria:** no, it primarily offloads reads; one shard receives disproportionate traffic; the query must coordinate results across servers.\n\n## Read further\n\n- [PostgreSQL: warm standby and streaming replication](https://www.postgresql.org/docs/current/warm-standby.html)\n- [PostgreSQL: table partitioning](https://www.postgresql.org/docs/current/ddl-partitioning.html)\n- [Azure Architecture Center: sharding pattern](https://learn.microsoft.com/azure/architecture/patterns/sharding)\n","07-consistency-and-time.md":"# Consistency, partitions, and time\n\n**Consistency** describes what different clients can observe about updates. The word has several precise meanings; choose a user-facing guarantee before choosing a database label. Our editor should see a confirmed version 8 on the next read. A public document count may tolerate a short delay. These are different contracts.\n\n## Name the observation you promise\n\n**Read-your-writes** means a client that successfully saved version 8 does not subsequently see version 7. **Eventual consistency** means replicas can temporarily disagree but converge if updates stop and communication resumes; it does not promise a particular delay. Some operations need stronger ordering, such as accepting only one successful update from a given base version. Use an authoritative primary transaction or a storage system with the required conditional write behavior.\n\nDuring a **network partition**, two sides cannot communicate. The familiar CAP result concerns whether a distributed data service can provide linearizable responses and availability to every request while that partition persists. It does **not** say systems choose only two properties for all time, nor that a database is simply “CP” or “AP” in every operation. The useful design question is: for this operation and failure, do we reject/delay a response or permit a response that may be stale or conflicting? A document edit should usually refuse to claim success without durable authoritative acceptance; a cached public thumbnail can often remain available.\n\nWall clocks can disagree across machines. Do not use client timestamps as the sole ordering or conflict rule. Use database-assigned versions or transaction sequence for edits; record wall-clock time for display and diagnostics. Clock skew can also affect token expiry and lease logic, so tolerate bounded skew and avoid treating a timestamp as proof of a unique global order.\n\n## Diagram: versioned read after write\n\n![A primary confirms version eight while a lagging replica still holds version seven; the editor's next read follows the primary or waits for the replica.](/learning/scale-design/consistency.svg)\n\n```aosdf-diagram\nEditor ──save v8──▶ PRIMARY v8 ──async copy──▶ REPLICA v7 → v8\nEditor ──next read──▶ PRIMARY v8 (or replica after v8 is visible)\n```\n\n## Implementation: express the promise in API and storage\n\nPostgreSQL's transaction isolation and conditional updates can enforce the edit version. OpenTelemetry can trace the save and the next read across primary and replica. Redis may serve eventually consistent counts or bounded-stale listings, but it should not become the sole authority for a confirmed edit.\n\n| Logo | Technology and documentation | Role in this design | Check before adopting |\n| :---: | --- | --- | --- |\n| ![postgresql logo](/learning/scale-design/logo-postgresql.svg) | [PostgreSQL transactions](https://www.postgresql.org/docs/current/transaction-iso.html) | Commit authoritative versions and access changes. | Choose isolation and retry behavior per invariant. |\n| ![opentelemetry logo](/learning/scale-design/logo-opentelemetry.svg) | [OpenTelemetry traces](https://opentelemetry.io/docs/concepts/signals/traces/) | Follow a write and subsequent read across data paths. | Correlate with version IDs, not document contents. |\n| ![redis logo](/learning/scale-design/logo-redis.svg) | [Redis](https://redis.io/docs/latest/develop/use-cases/cache-aside/) | Serve data explicitly allowed to be stale. | Write down TTL, invalidation, and fallback behavior. |\n\nA concrete HTTP contract is `PATCH /documents/42` with `If-Match: \"v7\"`. On a successful conditional update, return `ETag: \"v8\"`; on a stale precondition, return `412 Precondition Failed` and let the authorized client fetch the current version. The editor's next read must route to the primary or a replica known to have reached v8. [HTTP `If-Match`](https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/If-Match) is a useful protocol tool, but the database conditional write remains the enforcement point. During a partition, do not confirm an edit that the authoritative write path could not commit.\n\n## Engineering exercise\n\nClassify three actions: the editor's immediate read after save, a public count of document views, and granting a collaborator access. For each, state whether a stale response is acceptable, for how long, and what happens during a partition.\n\n## Design review questions\n\n- Does “eventual” specify an upper bound on staleness?\n- Why is CAP about the behavior during a partition?\n- What is safer than client wall-clock timestamps for edit ordering?\n\n**Review criteria:** no; partitions force a response-or-consistency decision for distributed operations; a server-controlled version or transactional compare-and-swap gives a clear order.\n\n## Read further\n\n- [Gilbert and Lynch: Brewer's conjecture and feasibility of consistent, available, partition-tolerant web services](https://groups.csail.mit.edu/tds/papers/Gilbert/Brewer2.pdf)\n- [Jepsen: consistency models](https://jepsen.io/consistency/models)\n- [PostgreSQL: transaction isolation](https://www.postgresql.org/docs/current/transaction-iso.html)\n","08-concurrency-and-runtime.md":"# Concurrency, locks, and runtime health\n\n**Concurrency** means work overlaps in time. The difficult case is not just many readers; it is two editors changing the same document or two processes claiming the same maintenance job. A **race condition** exists when the outcome depends on timing that the design has not controlled.\n\n## Protect simultaneous edits\n\nBoth editors read version 7. Alice saves first; Bob saves afterward. A blind `UPDATE` loses Alice's edit. With **optimistic concurrency**, Bob submits the version he read:\n\n```sql\nUPDATE documents\nSET title = $new_title, version = version + 1\nWHERE id = $id AND version = 7;\n```\n\nIf the affected-row count is zero, return a conflict and show the current version; do not silently overwrite. This fits conflicts that are relatively rare. **Pessimistic locking** reserves the row while a short transaction computes a change, useful when conflicts are common or a multi-step invariant needs protection. Keep lock order consistent and transactions short to reduce **deadlocks**; on deadlock or serialization failure, retry the *whole* transaction only when the operation is safe to retry.\n\nA distributed lock coordinates processes, but a lock lease can expire while a paused holder is still working. For a critical effect, use a fencing token or a storage-level conditional write so an old holder cannot act after a new leader. Leader election identifies one coordinator; it does not magically make its effects exactly once.\n\n## Keep the process healthy too\n\n**Thread safety** means shared in-memory state behaves correctly under concurrent execution. Avoid mutable global request state; protect shared structures or keep state local. A **memory leak** is memory that remains reachable but is no longer useful, such as unbounded in-memory document caches or event listeners never removed. Garbage collection reclaims unreachable objects, not objects a mistaken cache still references. Watch heap growth, GC pause time, allocation rate, and p99 latency under sustained load; restart policies only hide a leak temporarily.\n\n## Diagram: compare a version before saving\n\n![Two editors read version seven; Alice's conditional update creates version eight and Bob's stale update is rejected with a conflict.](/learning/scale-design/concurrency.svg)\n\n```aosdf-diagram\nAlice reads v7 ── conditional save ──▶ v8 success\nBob reads v7   ── conditional save ──▶ 0 rows → conflict, reload v8\n```\n\n## Implementation: enforce ownership where the effect occurs\n\nPostgreSQL row versions and locks guard document invariants. Redis can coordinate an advisory lease for a background coordinator, but an expired lease holder may still run. Prometheus process metrics make memory growth and pause time visible before p99 degrades.\n\n| Logo | Technology and documentation | Role in this design | Check before adopting |\n| :---: | --- | --- | --- |\n| ![postgresql logo](/learning/scale-design/logo-postgresql.svg) | [PostgreSQL locking](https://www.postgresql.org/docs/current/explicit-locking.html) | Apply row-level or optimistic concurrency to edits. | Keep transactions short and handle deadlock retries. |\n| ![redis logo](/learning/scale-design/logo-redis.svg) | [Redis distributed locks](https://redis.io/docs/latest/develop/use/patterns/distributed-locks/) | Coordinate best-effort exclusive work across processes. | Use fencing or a storage-level condition for critical effects. |\n| ![prometheus logo](/learning/scale-design/logo-prometheus.svg) | [Prometheus](https://prometheus.io/docs/introduction/overview/) | Observe heap, GC pauses, conflicts, and deadlocks. | Relate runtime metrics to request p99. |\n\nUse the SQL conditional `UPDATE ... WHERE id = $id AND version = $expected` from this lesson as the final authority for edits; check `row_count === 1`. If a Redis lease protects a scheduled cleanup job, include a monotonically increasing fencing token in writes to the downstream store or make the write conditional there. A lock key alone cannot prevent a paused old holder from resuming. Set a bounded in-process cache size and test steady-state heap after repeated document reads; a garbage collector cannot reclaim still-referenced entries.\n\n## Engineering exercise\n\nWrite the response to Bob after his version-7 update conflicts. Then describe a job coordinator whose lock expires mid-task; explain how a fencing token would prevent its old write. Name one metric that would reveal a leaking application cache.\n\n## Design review questions\n\n- Why does a mutex in one API instance not protect a document across the fleet?\n- Why can a stale lock holder still be dangerous?\n- Why does a garbage collector not fix an unbounded cache?\n\n**Review criteria:** other instances have separate memory; a paused holder may resume after its lease expires; cached objects remain reachable and therefore are not collectible.\n\n## Read further\n\n- [PostgreSQL: transaction isolation](https://www.postgresql.org/docs/current/transaction-iso.html)\n- [PostgreSQL: explicit locking](https://www.postgresql.org/docs/current/explicit-locking.html)\n- [Oracle Java: troubleshooting memory leaks](https://docs.oracle.com/en/java/javase/27/troubleshoot/troubleshooting-memory-leaks.html)\n","09-compatibility-and-review.md":"# Compatible change and architecture review\n\nA system is designed for change as well as traffic. During a rollout, old and new API processes, browser clients, and database rows coexist. A migration is safe when each intermediate state works and a rollback is understood.\n\n## Evolve the contract in stages\n\nSuppose documents gain `visibility` (`private` or `team`). First add a nullable database column and make old code ignore it. Deploy new readers that treat a missing value as `private`. Backfill existing rows in bounded batches. Deploy writers that set the field. Only after old writers have left service should you add a strict constraint, if needed. This is **expand, migrate, contract**. Keep access control conservative during the transition: never interpret an absent value as public.\n\nFor an HTTP API, adding an optional response field is usually less disruptive than renaming or removing one; test older clients. A new request field should have a safe default or explicit versioning. A URL version is one option, but versioning does not replace compatibility testing. **Semantic versioning** communicates intended compatibility for a versioned public interface or library; it does not automatically govern a continuously deployed internal API or database. Define the contract and deprecation period that clients actually use.\n\n## Review the design against evidence\n\nAn architecture review should list the user promise, peak estimate, p99 target, source of truth, authorization point, consistency contract, failure behavior, and rollback. For every cache, replica, or shard, name the measurement that justified it and the new failure mode. Model a primary outage: can reads continue, can edits be honestly accepted, how is failover verified, and what data loss could occur? Model an overloaded database: does the gateway reject excess work, or do retries amplify it? Capture the chosen trade-off and revisit it when traffic or requirements change.\n\nA useful rollout sequence is: add metrics and traces; deploy a compatible schema; release a small percentage of traffic; compare latency, errors, data correctness, and access decisions; expand only if healthy; retain a tested rollback path. A design is not complete if nobody can tell whether it meets its promise.\n\n## Diagram: safe contract evolution\n\n![Old and new clients coexist while a field is added, backfilled, then enforced after old writers are gone.](/learning/scale-design/compatibility.svg)\n\n```aosdf-diagram\nExpand schema ──▶ new readers with safe default ──▶ backfill\n          └──▶ new writers ──▶ observe ──▶ enforce constraint\n```\n\n## Implementation: automate the rollout contract\n\nA migration tool records schema versions, OpenAPI describes the HTTP contract, and metrics show whether a canary behaves as expected. Keep these artifacts in the same review as the code so the rollout sequence is executable, not just a diagram.\n\n| Logo | Technology and documentation | Role in this design | Check before adopting |\n| :---: | --- | --- | --- |\n| ![flyway logo](/learning/scale-design/logo-flyway.svg) | [Flyway](https://documentation.red-gate.com/flyway) | Apply ordered, reviewable database migrations. | Use an expand/backfill/contract sequence for live traffic. |\n| ![openapiinitiative logo](/learning/scale-design/logo-openapiinitiative.svg) | [OpenAPI Specification](https://spec.openapis.org/oas/) | Describe request fields, responses, and versioned behavior. | Test older clients against the new contract. |\n| ![prometheus logo](/learning/scale-design/logo-prometheus.svg) | [Prometheus](https://prometheus.io/docs/introduction/overview/) | Compare canary error rate and p99 with baseline. | Add a rollback trigger tied to user-visible failure. |\n\nA staged change might begin with a Flyway migration `V42__add_visibility.sql` containing `ALTER TABLE documents ADD COLUMN visibility text;`. New readers treat `NULL` as `private`. Backfill in bounded batches; deploy writers that set `visibility`; then add a constraint only after old writers are gone. Update the OpenAPI schema with the new optional field and run compatibility tests against the previous client. During a canary, compare access-denied errors, p99, and inconsistent visibility reports before increasing traffic. Rollback should leave a schema old code can still read.\n\n## Engineering exercise\n\nWrite a one-page design review for the shared document library. Include the 1,160-RPS peak assumption, a p99 target, the data and authorization path, cache policy, connection budget, immediate read-after-save behavior, conflict response, two failure drills, and a rollback. Identify which numbers must be replaced with measurements.\n\n## Design review questions\n\n- Why must a database migration work while old API instances still run?\n- Is a new URL version enough to guarantee compatibility?\n- What does a design review need besides a box-and-arrow diagram?\n\n**Review criteria:** rolling deploys overlap versions; clients and semantics still need tests and a migration path; requirements, evidence, failure contracts, and rollback make the diagram actionable.\n\n## Read further\n\n- [Semantic Versioning specification](https://semver.org/)\n- [Google SRE: service level objectives](https://sre.google/sre-book/service-level-objectives/)\n- [PostgreSQL: ALTER TABLE](https://www.postgresql.org/docs/current/sql-altertable.html)\n"}}},9617:(a,b,c)=>{Promise.resolve().then(c.t.bind(c,5547,23))},9889:(a,b,c)=>{Promise.resolve().then(c.t.bind(c,1921,23))}};